ST.xhtml:
{region "🎯 §1 Intention & assistants"}
// === 🪨 §1 INTENTION MAINTENANCE & ASSISTANTS ===

// Consommation de l'intention both continue opérateur (source unique PRG_03, tous modes)
WinchBothMotionActive    := PRG_03_Modes_Cycle.Data.WinchBothIntent.Active;
WinchBothReqAscent  := PRG_03_Modes_Cycle.Data.WinchBothIntent.ReqAscent;
WinchBothReqDescend := PRG_03_Modes_Cycle.Data.WinchBothIntent.ReqDescend;

// Récupération de l'état fond synthétisé par PRG_03
BottomPositionConfirmed := PRG_03_Modes_Cycle.Data.SequenceState.BottomTouchConfirmed;

// MODES DE MAINTENANCE (calculés en tête de scan : consommés dès §2 par instBucket)
// 🚨 DEROGATION MES septembre 2026 (AF-05 §4bis) : les bypass sécurité treuil M1/M2 + benne
// NE SONT PLUS conditionnés au mode. Un bypass IHM armé est effectif dans TOUS les modes
// (y compris SEMI_AUTO / AUTO). Choix opérateur assumé, tracé — voir AF-05 §4bis.
// MAINT_N1 reste utilisé pour l'override momentané du FDC haut logiciel (§5) et l'assistance extraction.
MaintN1 := (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N1);
// Séquence d'extraction active (mode MAINT + toggle) : gate le permis de montée assistée (§5).
// Le permis lui-même (AscentPermit) est produit par FB_ExtractionAssist et consommé via le contrat benne.
ExtractionAssistActive := (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N1 OR PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N2)
                          AND GVL_IHM.CycleExtraction.Cmd.TglEnableExtractionSequence;

// Règle absolue en pilotage both normal --
// descente autorisée UNIQUEMENT benne ouverte, montée UNIQUEMENT benne fermée.
// Décision déléguée à FB_BucketCmdArbitration (POO §5) : flags armés + commandes
// arbitrées (ouverture, fermeture, contacteur Kobold). Bit-identique PRG_04 §1/§2.
ArbBucketIHM.BtnOpen  := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnOpen;
ArbBucketIHM.BtnClose := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnClose;

ArbBucketContext.TglEnableCoupledBucketSequencing := GVL_IHM.Commun.Cfg.TglEnableCoupledBucketSequencing;
ArbBucketContext.MotionActive   := WinchBothMotionActive;
ArbBucketContext.ReqAscent      := WinchBothReqAscent;
ArbBucketContext.ReqDescend     := WinchBothReqDescend;
ArbBucketContext.BucketIsOpen   := _BucketState.IsOpen;
ArbBucketContext.BucketIsClosed := _BucketState.IsClosed;

instArbBucket(
    Enable    := TRUE,
    Auth      := PRG_03_Modes_Cycle.Data.Auth,
    ReqBucket := PRG_03_Modes_Cycle.Data.ReqProgram.ReqBucket,
    IHM       := ArbBucketIHM,
    Context   := ArbBucketContext
);
WinchBothDiveBucketOpenArmed    := instArbBucket.WinchBothDiveBucketOpenArmed;
WinchBothAscentBucketCloseArmed := instArbBucket.WinchBothAscentBucketCloseArmed;
CmdBucketCloseArbitrated        := instArbBucket.CmdClose_IHM;
KoboldContactorCmdArbitrated    := instArbBucket.KoboldContactorCmdArbitrated;

{endregion}

{region "🪣 §2 Commande benne"}
// === 🏗️ §2 COMMANDE DU BENNE (FB_Bucket) ===

instBucket(
    Enable              := NOT PRG_03_Modes_Cycle.Data.Auth.InhibitM2,
    Reset               := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged     := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                := PRG_03_Modes_Cycle.Data.Auth.Mode,
    CmdOpen_IHM         := instArbBucket.CmdOpen_IHM,
    CmdClose_IHM        := CmdBucketCloseArbitrated,
    ReqAscent           := WinchBothReqAscent,
    ReqDescend          := WinchBothReqDescend,
    EffectivePermitBucket_Open := EffectivePermitBucket_Open,
    EffectivePermitBucket_Close := EffectivePermitBucket_Close,
    CablePosM1          := PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM,
    CablePosM2          := PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM,
    HomedM1             := PRG_02_Acquisition.Data.EncoderM1.Homed,
    HomedM2             := PRG_02_Acquisition.Data.EncoderM2.Homed,
    M1_Busy             := (instWinchM1.StepNumber > 0),
    M2_Busy             := (instWinchM2.StepNumber > 0),
    // Confirmations visuelles N2 : publication et offset benne. Le preset
    // materiel M2 associe est produit independamment dans PRG_02.
    ConfirmOpenPosition  := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmOpenPos,
    ConfirmClosePosition := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmClosePos,
    MachineHomingCommitOpen  := PRG_02_Acquisition.Data.MachineHoming.SetPosBucketOpen,
    MachineHomingCommitClose := PRG_02_Acquisition.Data.MachineHoming.SetPosBucketClose,
    MachineHomed := PRG_02_Acquisition.Data.MachineHoming.Homed,
    MachineHomingActive := PRG_02_Acquisition.Data.MachineHoming.Active,
    Config              := _BucketCfgPersist.Config,
    CfgTimeoutDuration     := GVL_IHM.M2TreuilBenne.Bucket.Cfg.CfgTimeoutDuration,
    BucketState        := _BucketState,
    InhibitM1           := PRG_03_Modes_Cycle.Data.Auth.InhibitM1,
    InhibitM2           := PRG_03_Modes_Cycle.Data.Auth.InhibitM2,
    // Bypass benne (n°25 de la matrice) — effectif tous modes si armé (dérogation MES 2026, AF-05 §4bis)
    BypassGlobal        := GVL_IHM.M2TreuilBenne.Bucket.Bypass.Global
);

// Auto-séquencement benne & Dégradation Palier 1
// Si la benne est en cours de fermeture/ouverture (instBucket.Busy), le mouvement couplé attend.
// Si la benne n'est pas fermée (NOT IsClosed) et que instBucket n'est plus occupé (Busy=FALSE),
// toute demande de montée est automatiquement dégradée au Palier 1 (Vitesse lente, voir instWinchM1/M2),
// protégeant ainsi la mécanique même en pilotage unitaire ou si l'auto-séquencement est désactivé.
// 📌 Note d'architecture (lag 1 scan) : M1/M2LogicRequestDirection est consommé ici avant son calcul arbitré
// en §3 (lag d'un cycle automate nominal, toléré et homogène avec les arbitrages Translation/Modes).
WinchBothMotionBlockedByBucket := WinchBothDiveBucketOpenArmed AND NOT instBucket.Lifecycle.Busy;
BucketNotClosedAscentStep1 := (M1LogicReqAscent OR M2LogicReqAscent) AND NOT instBucket.Lifecycle.Busy AND NOT _BucketState.IsClosed;

// En mode récupération (SyncEnable=FALSE), si un mou de câble est détecté (bit3 ErrorId),
// la montée/enroulement est autorisée mais bridée au Palier 1 pour retendre le tambour en sécurité.
// 📌 Note d'architecture (lag 1 scan) : instSafetyWinchM1/M2.ErrorId est consommé ici avant l'exécution du FB
// au §5bis (lag d'un cycle automate nominal, sécurisé en amont par la lecture directe de M2_TensionedCable_DI).
SlackCableAscentStep1 := NOT GVL_IHM.Commun.Bypass.SlackCable
    AND NOT PRG_03_Modes_Cycle.Data.Auth.SyncEnable AND (
    ((instSafetyWinchM1.Fault.ErrorId AND 16#0008) <> 16#0000) OR
    ((instSafetyWinchM2.Fault.ErrorId AND 16#0008) <> 16#0000) OR
    (NOT PRG_02_Acquisition.HwIn.Winch.M2_TensionedCable_DI)
);

SyncMinorDeviation := (instWinchSync.Fault.ErrorId AND 16#0001) <> 16#0000;
// 🛡️ Soft-stop synchro : rattrapage directionnel volontaire UNIQUEMENT en
// commande unitaire. En commande BOTH (WinchBothMotionActive), l'écart mineur ne doit
// JAMAIS produire de rattrapage unilatéral d'un seul treuil — il est géré par le clamp
// palier §5ter (les 2 treuils sont bridés à 1) et le seuil critique (SafeStop des 2,
// §5). Donc les drapeaux sync sont coupés dès qu'un mouvement both est demandé.
SyncMinorDeviationBlocksUp   := _SyncSoftStopEnable AND SyncMinorDeviation AND (instWinchSync.SignedDeltaPosM > 0.0) AND NOT WinchBothMotionActive;
SyncMinorDeviationBlocksDown := _SyncSoftStopEnable AND SyncMinorDeviation AND (instWinchSync.SignedDeltaPosM < 0.0) AND NOT WinchBothMotionActive;

IF _CommunCfgPersist.WinchMaxStepAscent <= 0 THEN
    EffectiveMaxStepAscent := 5;
ELSE
    EffectiveMaxStepAscent := _CommunCfgPersist.WinchMaxStepAscent;
END_IF;

IF _CommunCfgPersist.WinchMaxStepDescent <= 0 THEN
    EffectiveMaxStepDescent := 5;
ELSE
    EffectiveMaxStepDescent := _CommunCfgPersist.WinchMaxStepDescent;
END_IF;


{endregion}

{region "🔀 §3 Arbitrage M1/M2"}
// === 🔀 §3 ARBITRAGE CONSIGNES M1 / M2 ===

// ── Arbitrage M1/M2 (FB_WinchCmdArbitrationM1/M2) ──
// Dérivation des bits d'action benne M2 (consommés par les 2 FB d'arbitrage)
BucketM2ReqAscent  := instBucket.M2_ReqAscent;
BucketM2ReqDescend := instBucket.M2_ReqDescend;

// Remplissage des structs d'arbitrage (champ par champ, CODESYS 3.5 refuse l'init anonyme en appel)
ArbIHM.BtnAscentM1           := GVL_IHM.M1TreuilRetenue.Cmd.BtnAscent;
ArbIHM.BtnDescentM1         := GVL_IHM.M1TreuilRetenue.Cmd.BtnDescent;
ArbIHM.BtnAscentM2           := GVL_IHM.M2TreuilBenne.Cmd.BtnAscent;
ArbIHM.BtnDescentM2         := GVL_IHM.M2TreuilBenne.Cmd.BtnDescent;
ArbIHM.BtnWinchBothAscent    := GVL_IHM.Commun.BtnWinchBothAscent;
ArbIHM.BtnWinchBothDescent  := GVL_IHM.Commun.BtnWinchBothDescent;

ArbContext.BucketBusy                     := instBucket.Lifecycle.Busy;
ArbContext.BucketM2RunRequest             := instBucket.M2_RunRequest;
ArbContext.BucketM2ReqAscent              := BucketM2ReqAscent;
ArbContext.BucketM2ReqDescend             := BucketM2ReqDescend;
ArbContext.WinchBothMotionBlockedByBucket := WinchBothMotionBlockedByBucket;
ArbContext.SyncBlocksAscent                   := SyncMinorDeviationBlocksUp;
ArbContext.SyncBlocksDescent                 := SyncMinorDeviationBlocksDown;
// 🔗 Atomicité Both : agrégats consommés par la commande both (§5 calcule
// Both*Permit APRÈS §3 → lag 1 scan assumé au gate d'arbitre, documenté comme les
// autres gates lag-1 de PRG_04 ; l'enforcement même-scan est assuré par le routage
// §6 vers FB_Winch).
ArbContext.M1AscentAllowed  := EffectivePermitM1_Ascent;
ArbContext.M1DescendAllowed := EffectivePermitM1_Descend;
ArbContext.M2AscentAllowed  := EffectivePermitM2_Ascent;
ArbContext.M2DescendAllowed := EffectivePermitM2_Descend;
ArbContext.BothBlock         := BothBlocked;

ArbM1Cfg.BtnStepTgt := 5;
ArbM2Cfg.BtnStepTgt := 5;
ArbM2Cfg.BucketOverrideStepTgt := 1;

// ── Arbitrage M1 (FB_WinchCmdArbitrationM1) ──
instArbM1(
    Enable     := TRUE,
    Joystick   := PRG_02_Acquisition.Data.Joystick,
    Auth       := PRG_03_Modes_Cycle.Data.Auth,
    ReqWinch   := PRG_03_Modes_Cycle.Data.ReqProgram.ReqWinchM1,
    BothIntent := PRG_03_Modes_Cycle.Data.WinchBothIntent,
    IHM        := ArbIHM,
    TglJoystickMaster := GVL_IHM.Modes.Cmd.TglJoystickMaster,
    Context    := ArbContext,
    Cfg        := ArbM1Cfg
);
M1LogicRunRequest := instArbM1.RunRequest;
M1LogicReqAscent  := instArbM1.ReqAscent;
M1LogicReqDescend := instArbM1.ReqDescend;
M1LogicRequestStepTgt := instArbM1.StepTgt;
// Diagnostic % (palier→%) pour IHM / simu — borne haute du palier arbitré.
IF (M1LogicRequestStepTgt >= 1) AND (M1LogicRequestStepTgt <= 5) THEN
    M1LogicRequestSpeedCmd_Pct := _WinchSpeedStepTable.StepThreshold_Pct[M1LogicRequestStepTgt];
ELSE
    M1LogicRequestSpeedCmd_Pct := 0.0;
END_IF;

// ── Arbitrage M2 (FB_WinchCmdArbitrationM2) ──
instArbM2(
    Enable     := TRUE,
    Joystick   := PRG_02_Acquisition.Data.Joystick,
    Auth       := PRG_03_Modes_Cycle.Data.Auth,
    ReqWinch   := PRG_03_Modes_Cycle.Data.ReqProgram.ReqWinchM2,
    BothIntent := PRG_03_Modes_Cycle.Data.WinchBothIntent,
    IHM        := ArbIHM,
    TglJoystickMaster := GVL_IHM.Modes.Cmd.TglJoystickMaster,
    Context    := ArbContext,
    Cfg        := ArbM2Cfg
);
M2LogicRunRequest := instArbM2.RunRequest;
M2LogicReqAscent  := instArbM2.ReqAscent;
M2LogicReqDescend := instArbM2.ReqDescend;
M2LogicRequestStepTgt := instArbM2.StepTgt;
// Diagnostic % (palier→%) pour IHM / simu — borne haute du palier arbitré.
IF (M2LogicRequestStepTgt >= 1) AND (M2LogicRequestStepTgt <= 5) THEN
    M2LogicRequestSpeedCmd_Pct := _WinchSpeedStepTable.StepThreshold_Pct[M2LogicRequestStepTgt];
ELSE
    M2LogicRequestSpeedCmd_Pct := 0.0;
END_IF;

// Front de fin d'action benne (F_TRIG conservé pour §3bis ArmingPermit et extraction control).
// L'arrêt forcé de fin d'action benne est désormais géré en interne par les FB d'arbitrage.
BenneBusyFallEdge(CLK := instBucket.Lifecycle.Busy);

// Après une fermeture benne armée PAR CE mécanisme
// (pas ExtractionAssist, qui a déjà sa propre phase CONTROL_ASCENT), la montée couplée qui
// enchaîne démarre en vitesse contrôlée (palier 1) sur ExtractionControlDistance_M avant de
// repasser en paliers normaux.
BucketBusyRiseEdge(CLK := instBucket.Lifecycle.Busy);
IF BucketBusyRiseEdge.Q THEN
    ControlAscentArmedForThisClose := WinchBothAscentBucketCloseArmed;
END_IF;
IF BucketBusyFallEdge.Q AND ControlAscentArmedForThisClose THEN
    ExtractionControlActive := TRUE;
    ControlAscentStartM1PosM := PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM;
    ControlAscentStartM2PosM := PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM;
END_IF;
IF ExtractionControlActive THEN
    IF (ABS(PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM - ControlAscentStartM1PosM) >= GVL_IHM.CycleExtraction.Cfg.ExtractionControlDistance_M)
       AND (ABS(PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM - ControlAscentStartM2PosM) >= GVL_IHM.CycleExtraction.Cfg.ExtractionControlDistance_M) THEN
        ExtractionControlActive := FALSE;         // Distance de contrôle parcourue : paliers normaux
    ELSIF NOT (WinchBothMotionActive AND WinchBothReqAscent) THEN
        ExtractionControlActive := FALSE;         // Ascending relâchée/interrompue : annule la phase
    END_IF;
END_IF;


{endregion}

{region "🛡️ §3bis ArmingPermit"}
// === 🛡️ §3bis ARMINGPERMIT (général — permis de mouvement) ===
// ArmingPermit = permission d'armement homme-mort (entrée FB_Joystick, consommée PRG_02).
// Règle générale : on ne peut armer QUE si au moins un axe (treuil M1/M2 ou translation M3)
// a un permis de mouvement effectif. Sinon, aucun mouvement n'est possible → armement inutile
// et trompeur (l'opérateur croit pouvoir bouger alors que tout est bloqué).
// Calcul déplacé après §5bis (où EffectivePermitM1/M2_Ascent/Descend sont disponibles).
// Combiné interlock benne conservé : interdit l'armement pendant une action benne
// (instBucket.Lifecycle.Busy) et 1 scan après (BenneBusyFallEdge.Q).
// Polarité positive (NC-100) : TRUE = armement autorisé.
{endregion}

{region "🔄 §4 Synchro M1/M2"}
// === 🔄 §4 SYNCHRONISATION M1 / M2 ===

instWinchSync(
    Enable          := PRG_03_Modes_Cycle.Data.Auth.SyncEnable AND NOT instBucket.Lifecycle.Busy
                        AND NOT PRG_02_Acquisition.Data.EncoderM1.Measurement.HomingLifecycle.Busy
                        AND NOT PRG_02_Acquisition.Data.EncoderM2.Measurement.HomingLifecycle.Busy
                        AND NOT PRG_03_Modes_Cycle.Data.Auth.InhibitM1 AND NOT PRG_03_Modes_Cycle.Data.Auth.InhibitM2,
    Reset           := PRG_07_Supervision.FaultMachineReset_IHM,
    Mode            := PRG_03_Modes_Cycle.Data.Auth.Mode,
    CablePosM1      := PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM,
    CablePosM2      := PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM,
    HomedAndReliableM1 := PRG_02_Acquisition.Data.EncoderM1.HomedAndReliable,
    HomedAndReliableM2 := PRG_02_Acquisition.Data.EncoderM2.HomedAndReliable,
    SyncEnable      := PRG_03_Modes_Cycle.Data.Auth.SyncEnable,
    CfgSyncToleranceM  := _SyncCfgPersist.CfgSyncTolerance_M,
    CfgSyncCriticalToleranceM := _SyncCfgPersist.CfgSyncCriticalTolerance_M,
    ActiveOffsetM   := instBucket.ActiveOffsetM,
    RelayFwdM1      := instWinchM1.RelayFwd,
    RelayFwdM2      := instWinchM2.RelayFwd,
    RelayRevM1      := instWinchM1.RelayRev,
    RelayRevM2      := instWinchM2.RelayRev,
    Contactor1_M1   := instWinchM1.Contactor1,
    Contactor1_M2   := instWinchM2.Contactor1,
    Contactor2_M1   := instWinchM1.Contactor2,
    Contactor2_M2   := instWinchM2.Contactor2,
    Contactor3_M1   := instWinchM1.Contactor3,
    Contactor3_M2   := instWinchM2.Contactor3,
    Contactor4_M1   := instWinchM1.Contactor4,
    Contactor4_M2   := instWinchM2.Contactor4,
    BypassGlobal    := GVL_IHM.M1M2Sync.Bypass.Global
);

// Pas de reconstruction de table M2 : le clamp §5ter (M2MaxStep* := 1) suffit
// — StepNumber ≤ 1 → seuls les états P1 sont commandés.
// M2 consomme directement _WinchSpeedStepTable (table normale).


{endregion}

{region "🔗 §5 Couplage & sécurités"}
// === 🛑 §5 COUPLAGE CROISÉ & SÉCURITÉS ===

// La limite légale (profondeur min. autorisée) doit elle aussi
// bénéficier du ralentissement progressif avant arrêt (comme la limite câble physique), pas juste
// un arrêt sec (DescendPermit). Comme les 2 limites bornent la même
// direction (descente), on alimente FB_Winch.BottomLimitM avec la PLUS RESTRICTIVE des deux
// (MAX de 2 valeurs négatives = celle la moins profonde = atteinte en premier) : le ralentissement
// (FB_Winch §"RALENTISSEMENT AUTOMATIQUE SUR BORDURES") s'enclenche alors sur la bonne limite,
// légale ou câble, sans dupliquer le mécanisme.
IF _CommunCfgPersist.LimitLegalEnabled THEN
    BottomLimitM1_Active := MAX(_WinchM1CfgPersist.CfgCableLimitDescent_M, _CommunCfgPersist.LimitLegalDepthMinAllowed_M);
    BottomLimitM2_Active := MAX(_WinchM2CfgPersist.CfgCableLimitDescent_M, _CommunCfgPersist.LimitLegalDepthMinAllowed_M);
ELSE
    BottomLimitM1_Active := _WinchM1CfgPersist.CfgCableLimitDescent_M;
    BottomLimitM2_Active := _WinchM2CfgPersist.CfgCableLimitDescent_M;
END_IF;

// 🩺 InputModuleFault (AF06 §3bis) : un module DI TOR hors service rend indisponibles
// les retours frein/thermique/contacteurs/fin de course des DEUX treuils (VH_0800END,
// Local_Digital_IO) — pas de granularité par treuil possible, donc SafeStop des DEUX.
// Perte d'une reference auparavant valide en mouvement : arret controle des
// deux treuils, sans PowerCutOff additionnel. Le cycle libere la demande
// seulement apres le composite d'arret mecanique confirme.
SafeStopM1_Raw      := ((instWinchSync.Fault.ErrorId AND 16#0002) <> 16#0000) OR instBucket.M1SlipDetected OR PRG_02_Acquisition.Data.InputModules.Fault
                       OR PRG_02_Acquisition.Data.MachineHoming.HomingLoss;
SafeStopM2_Raw      := ((instWinchSync.Fault.ErrorId AND 16#0002) <> 16#0000) OR PRG_02_Acquisition.Data.InputModules.Fault
                       OR PRG_02_Acquisition.Data.MachineHoming.HomingLoss;

// Surveillance Kobold descente normale (hors FB_DiveSearch)
// : signal HwIn.Machine.M1_M2_KoboldBottomTouch_DI (même que instDiveSearch §1).
KoboldAutoStopRiseEdge(CLK := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI);
KoboldAutoStopFallEdge(CLK := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI);

// Levée du verrou au neutre du joystick/boutons ou si toggle désactivé
IF PRG_02_Acquisition.Data.Joystick.AtNeutralXY OR NOT GVL_IHM.Commun.Cfg.TglEnableKoboldAutoStopDescent THEN
    KoboldImmersionConfirmed := FALSE;
    KoboldBottomTouchLatched := FALSE;
END_IF;

// WinchBothMotionActive requis : cette surveillance ne s'arme qu'en pilotage
// BOTH (Select=0), pas en pilotage unitaire M1 (où WinchBothMotionDirection reflète
// quand même l'axe joystick brut).
// Qualification immersion : front montant Kobold dans la fenêtre [ImmersionLower_M..ImmersionUpper_M]
IF GVL_IHM.Commun.Cfg.TglEnableKoboldAutoStopDescent
   AND WinchBothMotionActive
   AND WinchBothReqDescend
   AND _BucketState.IsOpen
   AND KoboldAutoStopRiseEdge.Q THEN
    IF (PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM <= _CycleDiveSearchCfgPersist.ImmersionUpper_M)
       AND (PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM >= _CycleDiveSearchCfgPersist.ImmersionLower_M)
       AND (PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM <= _CycleDiveSearchCfgPersist.ImmersionUpper_M)
       AND (PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM >= _CycleDiveSearchCfgPersist.ImmersionLower_M) THEN
        KoboldImmersionConfirmed := TRUE;
    END_IF;
END_IF;

// Détection fond : front descendant Kobold APRÈS immersion confirmée
IF KoboldAutoStopFallEdge.Q AND KoboldImmersionConfirmed THEN
    KoboldBottomTouchLatched := TRUE;
    KoboldImmersionConfirmed := FALSE;
END_IF;

// Autorisation directe et explicite issue de PRG_03 (DiveSearch / Cycle)
DescendPermitDiveBucketOpen := PRG_03_Modes_Cycle.Data.ReqProgram.ReqBucket.DescendPermitDiveBucketOpen;

// Le bypass arrête aussi la descente instantanément, même doctrine que le mécanisme
// KoboldBottomTouchLatched.
// Mode "pilotage unitaire M2 sécurisé"
// (SelJoystickWinch=2 + toggle IHM). Ne passe PAS par instBucket (pas de CloseReq/OpenReq
// mémorisé, jogging libre) -- bornes directes ouvert/fermé (mêmes offsets que FB_Bucket,
// relatifs à la position réelle de M1) + palier 1 (voir instWinchM2 §6 plus bas).
ManualBucketLimitsActive := GVL_IHM.M2TreuilBenne.Bucket.Cmd.TglManualBucketLimits
    AND (PRG_03_Modes_Cycle.Data.Auth.JoystickWinchSelectArbitrated = 2);

ProcessPermitM1_Descend := NOT (KoboldBottomTouchLatched OR BypassKoboldBottomTouched) AND DescendPermitDiveBucketOpen;
// Ce chemin (pilotage
// unitaire M2, hors instBucket) applique l'anticipation d'inertie OpenAnticipationM/CloseAnticipationM
// (mêmes que FB_Bucket) pour couvrir aussi le jog unitaire.
ProcessPermitM2_Descend := NOT (KoboldBottomTouchLatched OR BypassKoboldBottomTouched) AND DescendPermitDiveBucketOpen
    AND NOT (ManualBucketLimitsActive AND (PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM <= (PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM + _BucketCfgPersist.Config.OffsetOpenM + _BucketCfgPersist.Config.OpenAnticipationM)));

// Permis process de montee : contrat extraction commun aux deux axes.
// M2 conserve l'anticipation de fermeture du pilotage benne unitaire, deja appliquee
// historiquement dans ProcessAndSafetyPermitM2_Ascent (refactor sans changement fonctionnel).
ProcessPermitM1_Ascent := NOT ExtractionAssistActive
    OR PRG_03_Modes_Cycle.Data.ReqProgram.ReqBucket.AscentPermit;
ProcessPermitM2_Ascent := (NOT ExtractionAssistActive
    OR PRG_03_Modes_Cycle.Data.ReqProgram.ReqBucket.AscentPermit)
    AND NOT (ManualBucketLimitsActive AND (PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM >= (PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM + _BucketCfgPersist.Config.OffsetCloseM - _BucketCfgPersist.Config.CloseAnticipationM)));

M2_LimitShift := SEL(_BucketState.IsClosed OR instBucket.CloseReq OR (PRG_03_Modes_Cycle.Data.Auth.JoystickWinchSelectArbitrated = 2),
                      0.0,
                      (PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM + _BucketCfgPersist.Config.OffsetCloseM + 0.5)
                      - _CommunCfgPersist.CfgCableLimitAscent_M);

{endregion}

{region "🧮 §5-0 Matrice N1/N2"}
// === 🛡️ §5-0 MATRICE DE MAINTENANCE (AF-05 §4bis) ===
// 🚨 DEROGATION MES septembre 2026 : bypass_effectif := bypass_IHM (armé) — SANS conditionnement
// de mode. Un bypass IHM armé est effectif dans TOUS les modes, SEMI_AUTO et AUTO inclus.
// Écart assumé (Directive Machines / ISO 13849) : traçabilité IHM + doc AF-05 §4bis.
// L'override du FDC haut logiciel reste momentané et propre à MAINT_N1 (§ ci-dessous).

// --- Override FDC haut LOGICIEL (décision Q8) ---------------------------------------------
// MAINT_N1 + bouton IHM MAINTENU ➔ la limite logicielle passe de 7,5 m à la position du capteur
// de homing haut (8,5 m). Relâché ➔ retour à 7,5 m au cycle suivant (aucune mémorisation).
// ⛔ Cet override n'ouvre PAS BypassTopLimitSwitch : le capteur physique haut reste la butée
// dure — si TopPositionSensor retombe, AscentPermit tombe (FB_Safety_Winch §3) ➔ arrêt matériel.
// ⛔ Conditionné à Homed ET NON HomingSuspect : sans référence de position fiable, la butée
// logicielle de FB_Safety_Winch (§3) ET la zone de ralentissement de FB_Winch (§3) sont
// neutralisées — relever la limite dans ce cas ne laisserait QUE le capteur physique comme
// protection, approché à pleine vitesse. Sans référence, il n'y a pas de « dépassement
// contrôlé » : l'override est refusé, seul reste le bypass N2 (acte conscient, tracé).
OverrideTopSoftwareN1M1 := MaintN1
                           AND PRG_02_Acquisition.Data.EncoderM1.Homed
                           AND NOT PRG_02_Acquisition.Data.EncoderM1.HomingSuspect
                           AND GVL_IHM.M1TreuilRetenue.Cmd.BtnOverrideTopSoftware;
OverrideTopSoftwareN1M2 := MaintN1
                           AND PRG_02_Acquisition.Data.EncoderM2.Homed
                           AND NOT PRG_02_Acquisition.Data.EncoderM2.HomingSuspect
                           AND GVL_IHM.M2TreuilBenne.Cmd.BtnOverrideTopSoftware;

// --- Bypass EFFECTIFS de la famille position (individuel OR commun, SANS gate de mode — dérogation MES 2026) ---
BypassM1TopLimitSwitchEff   := (GVL_IHM.M1TreuilRetenue.Bypass.TopLimitSwitch   OR GVL_IHM.Commun.Bypass.TopLimitSwitch);
BypassM1TopLimitSoftwareEff := (GVL_IHM.M1TreuilRetenue.Bypass.TopLimitSoftware OR GVL_IHM.Commun.Bypass.TopLimitSoftware);
BypassM1CableLimitSwitchEff := (GVL_IHM.M1TreuilRetenue.Bypass.CableLimitSwitch OR GVL_IHM.Commun.Bypass.CableLimitSwitch);
BypassM1LimitLegalEff       := (GVL_IHM.M1TreuilRetenue.Bypass.LimitLegal       OR GVL_IHM.Commun.Bypass.LimitLegal);
BypassM1MecaDEff            := GVL_IHM.M1TreuilRetenue.Bypass.MecaD;
BypassM2TopLimitSwitchEff   := (GVL_IHM.M2TreuilBenne.Bypass.TopLimitSwitch      OR GVL_IHM.Commun.Bypass.TopLimitSwitch);
BypassM2TopLimitSoftwareEff := (GVL_IHM.M2TreuilBenne.Bypass.TopLimitSoftware    OR GVL_IHM.Commun.Bypass.TopLimitSoftware);
BypassM2CableLimitSwitchEff := (GVL_IHM.M2TreuilBenne.Bypass.CableLimitSwitch    OR GVL_IHM.Commun.Bypass.CableLimitSwitch);
BypassM2LimitLegalEff       := (GVL_IHM.M2TreuilBenne.Bypass.LimitLegal          OR GVL_IHM.Commun.Bypass.LimitLegal);
BypassM2MecaDEff            := GVL_IHM.M2TreuilBenne.Bypass.MecaD;

// --- Limite haute logicielle active -------------------------------------------------------
// Nominal 7,5 m (CfgCableLimitAscent_M) ; 8,5 m (CfgTopSensorPos_M) sous override N1 momentané
// ou bypass N2 latché du FDC logiciel. M2 conserve son décalage benne (M2_LimitShift) dans les
// deux cas : l'override ne modifie que l'assiette de référence, pas la géométrie M1/M2.
// Le seuil haut nominal est un arrêt immédiat (distance de ralentissement = 0 m).
// En override/bypass MAINT, seul le FDC haut matériel définit la borne : il reste non-bypassable.
TopLimitM1_M := SEL(OverrideTopSoftwareN1M1 OR BypassM1TopLimitSoftwareEff,
                    _CommunCfgPersist.CfgCableLimitAscent_M,
                    _WinchM1CfgPersist.CfgTopSensorPos_M);
TopLimitM2_M := SEL(OverrideTopSoftwareN1M2 OR BypassM2TopLimitSoftwareEff,
                    _CommunCfgPersist.CfgCableLimitAscent_M + M2_LimitShift,
                    _WinchM2CfgPersist.CfgTopSensorPos_M + M2_LimitShift);

// --- Usage effectif d'un override/bypass de position → re-homing obligatoire ---------------
// Publié vers PRG_03 (rang 03) ➔ FB_Modes arme HomingRequiredMx à la sortie du mode maintenance.
// Famille position : TopLimitSwitch, TopLimitSoftware, CableLimitSwitch, LimitLegal, MecaD
// (+ l'override N1 momentané).
PositionLimitOverriddenM1 := OverrideTopSoftwareN1M1 OR BypassM1TopLimitSwitchEff
                             OR BypassM1TopLimitSoftwareEff OR BypassM1CableLimitSwitchEff
                             OR BypassM1LimitLegalEff OR BypassM1MecaDEff;
PositionLimitOverriddenM2 := OverrideTopSoftwareN1M2 OR BypassM2TopLimitSwitchEff
                             OR BypassM2TopLimitSoftwareEff OR BypassM2CableLimitSwitchEff
                             OR BypassM2LimitLegalEff OR BypassM2MecaDEff;
{endregion}

{region "🛡️ §5bis Sécurité M1/M2"}

// FB_Safety_Winch M1/M2.
// Instancié avant instWinchM1/M2 : MovementCommanded lit RelayFwd/RelayRev du scan précédent
// (même lag 1 scan accepté que M4/Translation, jamais sur Reset/SafeStop/PowerCutOff/sortie finale).
instSafetyWinchM1(
    Enable                 := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE) AND NOT PRG_03_Modes_Cycle.Data.Auth.InhibitM1,
    Reset                  := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged  := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                   := PRG_03_Modes_Cycle.Data.Auth.Mode,
    SyncEnable             := PRG_03_Modes_Cycle.Data.Auth.SyncEnable,
    JoystickOnline         := PRG_02_Acquisition.Data.Network.Joystick.Online,
    JoystickOperational    := PRG_02_Acquisition.Data.Network.Joystick.Operational,
    HeartbeatIhmOk         := GVL_IHM.Commun.HeartbeatIhmOk,
    EncoderAvailable       := PRG_02_Acquisition.Data.EncoderM1.Measurement.EncoderAvailable,
    EncoderFaultBypass     := GVL_IHM.M1TreuilRetenue.Bypass.EncoderFault,
    ThermalFeedback        := NOT PRG_02_Acquisition.HwIn.Winch.M1_ThermalOk_DI,
    BrakeThermalFeedback   := NOT PRG_02_Acquisition.HwIn.Machine.M1_M2_M3_BrakeThermalOk_DI,
    SlackCableDetected     := NOT PRG_02_Acquisition.HwIn.Winch.M2_TensionedCable_DI,
    PhaseRotationOk        := PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI,
    TopPositionSensor      := PRG_02_Acquisition.HwIn.Winch.M1M2_TopPositionFree_DI,
    InReferencingMode      := PRG_02_Acquisition.Data.EncoderM1.Measurement.HomingLifecycle.Busy,
    CablePosM              := PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM,
    CfgCableLimitDescentM  := _WinchM1CfgPersist.CfgCableLimitDescent_M,
    LimitLegalReached      := GVL_IHM.Commun.LimitLegalReached,
    ReqAscent              := M1LogicReqAscent,
    ReqDescend             := M1LogicReqDescend,
    MovementCommanded      := instWinchM1.RelayFwd OR instWinchM1.RelayRev,
    Homed                  := PRG_02_Acquisition.Data.EncoderM1.Homed,
    HomingSuspect          := PRG_02_Acquisition.Data.EncoderM1.HomingSuspect,
    TopLimitM              := TopLimitM1_M,
    FwdRevSpeedFeedbackOff := PRG_02_Acquisition.HwIn.Winch.M1_ContactorsReleased_DI,
    BrakeFeedback          := PRG_02_Acquisition.HwIn.Winch.M1_BrakeIsOpen_DI,
    JoystickYNeutral       := (PRG_02_Acquisition.Data.Joystick.AxisY.Direction = 0),
    BenneHoldStillActive   := instBucket.Lifecycle.Busy,
    ExpectedOtherWinchPosM := PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM - instBucket.ActiveOffsetM,
    BenneBusy              := instBucket.Lifecycle.Busy,
    OtherWinchInhibited    := PRG_03_Modes_Cycle.Data.Auth.InhibitM2,
    MeasuredSpeedMps       := PRG_02_Acquisition.Data.EncoderM1.Measurement.Speed_Mps,
    MeasuredSpeedSignedMps := PRG_02_Acquisition.Data.EncoderM1.Measurement.SignedSpeed_Mps,
    MeasuredSpeedValid     := PRG_02_Acquisition.Data.EncoderM1.Measurement.SpeedValid,
    SpeedBandMaxMps        := _WinchSpeedConfig.SpeedBandMaxMps[5],
    // Matrice AF-05 §4bis : bypass transmis SANS gate de mode (dérogation MES 2026, tous modes).
    // Le bypass commun reste en OR avec l'individuel (pilotage "both") — câblage d'origine inchangé.
    BypassGlobal           := GVL_IHM.M1TreuilRetenue.Bypass.Global,
    BypassSafety           := GVL_IHM.M1TreuilRetenue.Bypass.Safety,
    BypassProcess          := (GVL_IHM.M1TreuilRetenue.Bypass.Process
                              OR GVL_IHM.Commun.Bypass.SlackCable),
    // OR avec le bypass commun (Commun.Bypass) -- leve la
    // protection sur les 2 treuils simultanement pour le pilotage "both", sans retirer le
    // bypass individuel pour le pilotage a l'unite.
    BypassTopLimitSwitch   := BypassM1TopLimitSwitchEff,
    BypassTopLimitSoftware := BypassM1TopLimitSoftwareEff,
    BypassCableLimitSwitch := BypassM1CableLimitSwitchEff,
    BypassLimitLegal       := BypassM1LimitLegalEff,
    BypassOperatorComm     := GVL_IHM.M1TreuilRetenue.Bypass.OperatorComm,
    BypassPhaseRotation    := GVL_IHM.M1TreuilRetenue.Bypass.PhaseRotation,
    BypassBrakeThermal     := GVL_IHM.M1TreuilRetenue.Bypass.BrakeThermal,
    BypassMotorThermal     := GVL_IHM.M1TreuilRetenue.Bypass.MotorThermal,
    BypassMecaA            := GVL_IHM.M1TreuilRetenue.Bypass.MecaA,
    BypassMecaB            := GVL_IHM.M1TreuilRetenue.Bypass.MecaB,
    BypassMecaC            := GVL_IHM.M1TreuilRetenue.Bypass.MecaC,
    BypassMecaD            := BypassM1MecaDEff,
    BypassMecaE            := GVL_IHM.M1TreuilRetenue.Bypass.MecaE
);

instSafetyWinchM2(
    Enable                 := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE) AND NOT PRG_03_Modes_Cycle.Data.Auth.InhibitM2,
    Reset                  := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged  := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                   := PRG_03_Modes_Cycle.Data.Auth.Mode,
    SyncEnable             := PRG_03_Modes_Cycle.Data.Auth.SyncEnable,
    JoystickOnline         := PRG_02_Acquisition.Data.Network.Joystick.Online,
    JoystickOperational    := PRG_02_Acquisition.Data.Network.Joystick.Operational,
    HeartbeatIhmOk         := GVL_IHM.Commun.HeartbeatIhmOk,
    EncoderAvailable       := PRG_02_Acquisition.Data.EncoderM2.Measurement.EncoderAvailable,
    EncoderFaultBypass     := GVL_IHM.M2TreuilBenne.Bypass.EncoderFault,
    ThermalFeedback        := NOT PRG_02_Acquisition.HwIn.Winch.M2_ThermalOk_DI,
    BrakeThermalFeedback   := NOT PRG_02_Acquisition.HwIn.Machine.M1_M2_M3_BrakeThermalOk_DI,
    SlackCableDetected     := NOT PRG_02_Acquisition.HwIn.Winch.M2_TensionedCable_DI,
    PhaseRotationOk        := PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI,
    TopPositionSensor      := PRG_02_Acquisition.HwIn.Winch.M1M2_TopPositionFree_DI,
    InReferencingMode      := PRG_02_Acquisition.Data.EncoderM2.Measurement.HomingLifecycle.Busy,
    CablePosM              := PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM,
    CfgCableLimitDescentM  := _WinchM2CfgPersist.CfgCableLimitDescent_M,
    LimitLegalReached      := GVL_IHM.Commun.LimitLegalReached,
    ReqAscent              := M2LogicReqAscent,
    ReqDescend             := M2LogicReqDescend,
    MovementCommanded      := instWinchM2.RelayFwd OR instWinchM2.RelayRev,
    Homed                  := PRG_02_Acquisition.Data.EncoderM2.Homed,
    HomingSuspect          := PRG_02_Acquisition.Data.EncoderM2.HomingSuspect,
    TopLimitM              := TopLimitM2_M,
    FwdRevSpeedFeedbackOff := PRG_02_Acquisition.HwIn.Winch.M2_ContactorsReleased_DI,
    BrakeFeedback          := PRG_02_Acquisition.HwIn.Winch.M2_BrakeIsOpen_DI,
    JoystickYNeutral       := (PRG_02_Acquisition.Data.Joystick.AxisY.Direction = 0),
    BenneHoldStillActive   := FALSE,
    ExpectedOtherWinchPosM := PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM + instBucket.ActiveOffsetM,
    BenneBusy              := instBucket.Lifecycle.Busy,
    OtherWinchInhibited    := PRG_03_Modes_Cycle.Data.Auth.InhibitM1,
    MeasuredSpeedMps       := PRG_02_Acquisition.Data.EncoderM2.Measurement.Speed_Mps,
    MeasuredSpeedSignedMps := PRG_02_Acquisition.Data.EncoderM2.Measurement.SignedSpeed_Mps,
    MeasuredSpeedValid     := PRG_02_Acquisition.Data.EncoderM2.Measurement.SpeedValid,
    SpeedBandMaxMps        := _WinchSpeedConfig.SpeedBandMaxMps[5],
    // Matrice AF-05 §4bis (identique à M1 ci-dessus)
    BypassGlobal           := GVL_IHM.M2TreuilBenne.Bypass.Global,
    BypassSafety           := GVL_IHM.M2TreuilBenne.Bypass.Safety,
    BypassProcess          := (GVL_IHM.M2TreuilBenne.Bypass.Process
                              OR GVL_IHM.Commun.Bypass.SlackCable),
    // OR avec le bypass commun (Commun.Bypass) -- voir M1 ci-dessus
    BypassTopLimitSwitch   := BypassM2TopLimitSwitchEff,
    BypassTopLimitSoftware := BypassM2TopLimitSoftwareEff,
    BypassCableLimitSwitch := BypassM2CableLimitSwitchEff,
    BypassLimitLegal       := BypassM2LimitLegalEff,
    BypassOperatorComm     := GVL_IHM.M2TreuilBenne.Bypass.OperatorComm,
    BypassPhaseRotation    := GVL_IHM.M2TreuilBenne.Bypass.PhaseRotation,
    BypassBrakeThermal     := GVL_IHM.M2TreuilBenne.Bypass.BrakeThermal,
    BypassMotorThermal     := GVL_IHM.M2TreuilBenne.Bypass.MotorThermal,
    BypassMecaA            := GVL_IHM.M2TreuilBenne.Bypass.MecaA,
    BypassMecaB            := GVL_IHM.M2TreuilBenne.Bypass.MecaB,
    BypassMecaC            := GVL_IHM.M2TreuilBenne.Bypass.MecaC,
    BypassMecaD            := BypassM2MecaDEff,
    BypassMecaE            := GVL_IHM.M2TreuilBenne.Bypass.MecaE
);

SafeStopM1_Raw := SafeStopM1_Raw OR instSafetyWinchM1.SafeStop;
SafeStopM2_Raw := SafeStopM2_Raw OR instSafetyWinchM2.SafeStop;
// SafetyPermit = sorties FB_Safety_Winch (safety pure)
SafetyPermitM1_Descend := instSafetyWinchM1.DescendPermit;
SafetyPermitM2_Descend := instSafetyWinchM2.DescendPermit;
SafetyPermitM1_Ascent  := instSafetyWinchM1.AscentPermit;
SafetyPermitM2_Ascent  := instSafetyWinchM2.AscentPermit;
// ProcessAndSafetyPermit = Safety AND Process (ex _Raw)
ProcessAndSafetyPermitM1_Descend := ProcessPermitM1_Descend AND SafetyPermitM1_Descend;
ProcessAndSafetyPermitM2_Descend := ProcessPermitM2_Descend AND SafetyPermitM2_Descend;

// Mode "vidage à la trémie" : descente M1 ET M2 interdite tant
// que M3 n'est pas à P1 (travail) ou en position Maintenance -- verrouille la séquence
// descente-treuil / translation pour se rapprocher d'un enchaînement automatique sûr.
// Décision et calcul centralisés dans PRG_03_Modes_Cycle.Data.SequenceState.DumpAtTremieDescentLocked
IF PRG_03_Modes_Cycle.Data.SequenceState.DumpAtTremieDescentLocked THEN
    ProcessAndSafetyPermitM1_Descend := FALSE;
    ProcessAndSafetyPermitM2_Descend := FALSE;
END_IF;
// Permis de montée assistée : consommé depuis FB_ExtractionAssist (via le contrat benne).
// Hors extraction (NOT ExtractionAssistActive), la montée reste libre ; pendant l'extraction,
// la montée n'est autorisée que si l'assistant la délivre (AscentPermit, qui intègre les
// conditions process AscentControlSafe/AscentNominalSafe). Polarité fail-safe (TRUE = autorisé).
ProcessAndSafetyPermitM1_Ascent := ProcessPermitM1_Ascent AND SafetyPermitM1_Ascent;
ProcessAndSafetyPermitM2_Ascent := ProcessPermitM2_Ascent AND SafetyPermitM2_Ascent;

// 🔗 Couplage atomique M1/M2 : indépendant de SyncEnable. Actif en synchro
// classique (anti-télescopage) OU dès qu'un mouvement both est demandé — même si
// SyncEnable=FALSE (ex. MAINT_N2). Permet qu'une permission ou un SafeStop d'un
// treuil bloque l'autre : départ jamais isolé. WinchBothMotionActive est défini en
// §1 (disponible avant §5).
CoupledBoth := instWinchSync.SyncActive OR WinchBothMotionActive;

SafeStopM1_Active := SafeStopM1_Raw OR (CoupledBoth AND SafeStopM2_Raw);
SafeStopM2_Active := SafeStopM2_Raw OR (CoupledBoth AND SafeStopM1_Raw);
// EffectivePermit = ProcessAndSafetyPermit combine au couplage synchro (anti-télescopage)
// ET gaté par NOT SafeStop (défauts thermique/phase/codeur/méca) : le permit reflète « prêt à
// fonctionner », aligné sur M3 (PRG_05 §1ter). SafeStopM1/M2_Active agrège déjà le couplage
// synchro (SafeStop de l'autre treuil pendant SyncActive) — cohérent avec l'anti-télescopage.
EffectivePermitM1_Descend := ProcessAndSafetyPermitM1_Descend AND NOT SafeStopM1_Active AND (NOT CoupledBoth OR ProcessAndSafetyPermitM2_Descend);
EffectivePermitM2_Descend := ProcessAndSafetyPermitM2_Descend AND NOT SafeStopM2_Active AND (NOT CoupledBoth OR ProcessAndSafetyPermitM1_Descend);
EffectivePermitM1_Ascent  := ProcessAndSafetyPermitM1_Ascent  AND NOT SafeStopM1_Active AND (NOT CoupledBoth OR ProcessAndSafetyPermitM2_Ascent);
EffectivePermitM2_Ascent  := ProcessAndSafetyPermitM2_Ascent  AND NOT SafeStopM2_Active AND (NOT CoupledBoth OR ProcessAndSafetyPermitM1_Ascent);

// Permis canoniques benne : ouverture = M2 vers le bas, fermeture = M2 vers le haut.
// Les fins de course benne restent des faits fonctionnels distincts des limites treuil.
EffectivePermitBucket_Open := EffectivePermitM2_Descend
    AND PRG_02_Acquisition.Data.EncoderM1.Homed
    AND PRG_02_Acquisition.Data.EncoderM2.Homed
    AND (instBucket.Lifecycle.Busy OR NOT _BucketState.IsOpen)
    AND NOT instBucket.Fault.Error;
EffectivePermitBucket_Close := EffectivePermitM2_Ascent
    AND PRG_02_Acquisition.Data.EncoderM1.Homed
    AND PRG_02_Acquisition.Data.EncoderM2.Homed
    AND (instBucket.Lifecycle.Busy OR NOT _BucketState.IsClosed)
    AND NOT instBucket.Fault.Error;

// Défense en profondeur benne : le permis directionnel benne est appliqué au
// même scan aux deux niveaux M2, uniquement lorsque FB_Bucket est producteur.
M2AscentPermitApplied := EffectivePermitM2_Ascent
    AND (NOT instBucket.M2_RunRequest OR EffectivePermitBucket_Close);
M2DescendPermitApplied := EffectivePermitM2_Descend
    AND (NOT instBucket.M2_RunRequest OR EffectivePermitBucket_Open);

// 🔗 Agrégats Both : permis communs consommés par la commande both.
// = AND des 4 permits effectifs. Chaque axe garde sa vérité propre
// (EffectivePermitM*_*) ; en commande both, seul l'agrégat est consommé (§6),
// garantissant "les 2 treuils partent ensemble, ou aucun".

// 📉 Diagnostic IHM — cause priorisée du blocage Both (lecture seule, NC-100).
// N'a AUCUN effet de conduite : l'arrêt est porté par Both*Permit (§6, consommé par les
// 2 FB_Winch) et la défense en profondeur par la barrière finale (FB_WinchOutputInterlock,
// coupe par PermitFinalBlocked). Ordre : cause la plus grave gagne.
IF NOT WinchBothMotionActive THEN
    BothBlocked             := FALSE;
    BothBlockReason         := E_WinchTraceBlockReason.NONE;
ELSIF NOT ((WinchBothReqAscent AND EffectivePermitM1_Ascent AND EffectivePermitM2_Ascent)
        OR (WinchBothReqDescend AND EffectivePermitM1_Descend AND EffectivePermitM2_Descend)) THEN
    BothBlocked             := TRUE;
    BothBlockReason         := E_WinchTraceBlockReason.COUPLING_BLOCKED;
ELSE
    BothBlocked             := FALSE;
    BothBlockReason         := E_WinchTraceBlockReason.NONE;
END_IF;

// 🛡️ ArmingPermit (général — permis de mouvement) : on ne peut armer QUE si au moins
// un axe (treuil M1/M2 ou translation M3) a un permis de mouvement effectif.
// M3 : NOT TranslationSafety.SafeStop = permis de mouvement translation.
// Combiné interlock benne conservé (pas d'armement pendant action benne + 1 scan).
ArmingPermit := (EffectivePermitM1_Ascent OR EffectivePermitM1_Descend
              OR EffectivePermitM2_Ascent OR EffectivePermitM2_Descend
              OR NOT PRG_05_Translation.Data.TranslationSafety.SafeStop)
              AND NOT instBucket.Lifecycle.Busy AND NOT BenneBusyFallEdge.Q;


{endregion}

{region "📐 §5ter Clamp palier"}
// === 🧮 §5ter AGRÉGATEUR DE CLAMP DE PALIER ===
// Bornes communes identiques M1=M2, puis M2 applique ses limites benne propres.
// Plafond = MIN des sources plafond ; plancher = MAX des sources plancher ; plafond gagne.
// Synchro (instWinchSync) calculée en §4, en amont : SyncDeviationWarn réduit les DEUX treuils.

// --- Sources communes (M1 = M2) ---
CommonMaxStepAscent   := EffectiveMaxStepAscent;
CommonMaxStepDescent := EffectiveMaxStepDescent;
IF instWinchSync.SyncDeviationWarn THEN
    CommonMaxStepAscent   := 1;
    CommonMaxStepDescent := 1;
END_IF;
IF PRG_03_Modes_Cycle.Data.ReqProgram.ReqBucket.ExtractionControlActive OR ExtractionControlActive THEN
    CommonMaxStepAscent := 1;
END_IF;

// Planchers communs : 1 (neutre) en montée ; en descente, 0 hors plongée.
// MinStepDown=0 signifie explicitement « aucun plancher » : seul FB_DiveSearch
// peut imposer un palier de plongée. Ne jamais réintroduire un minimum à 1 ici,
// sinon une inversion de sens ne peut plus atteindre StepNumber=0.
// Règle de l'agrégateur : plancher = MAX des sources plancher ; si plancher > plafond,
// LE PLAFOND GAGNE — le clamp final (consommation FB_Winch, lot aval) borne au plafond,
// on ne force donc jamais ici un palier au-delà de CommonMaxStepDescent.
CommonMinStepUp   := 1;
CommonMinStepDown := MAX(0, PRG_03_Modes_Cycle.Data.ReqProgram.ReqBucket.MinStepDown);

// --- M2-propre (jamais vu par M1) ---
M2MaxStepUp   := CommonMaxStepAscent;
M2MaxStepDown := CommonMaxStepDescent;
IF instBucket.M2_BucketJogLimit OR ManualBucketLimitsActive THEN
    M2MaxStepUp   := 1;
    M2MaxStepDown := 1;
END_IF;
IF BucketNotClosedAscentStep1 OR SlackCableAscentStep1 THEN
    M2MaxStepUp := 1;
END_IF;
M2MinStepUp   := CommonMinStepUp;
M2MinStepDown := CommonMinStepDown;
{endregion}

{region "⚙️ §6 Exécution M1/M2"}
// === ⚙️ §6 EXÉCUTION FB_Winch (M1 & M2) ===

// Estimateurs de bande vitesse réelle appelés AVANT instWinchM1/M2 : leur sortie
// SpeedBand alimente MeasuredSpeedBand (2e étage du garde-fou FB_Winch) sur le même
// scan. Sources vitesse identiques à FB_Safety_Winch (§5bis).
instWinchLoadEstimatorM1(
    Enable                  := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE) AND NOT PRG_03_Modes_Cycle.Data.Auth.InhibitM1,
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    Mode                    := PRG_03_Modes_Cycle.Data.Auth.Mode,
    ActiveSpeedStep         := instWinchM1.StepNumber,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    MeasuredSpeedMps        := PRG_02_Acquisition.Data.EncoderM1.Measurement.Speed_Mps,
    MeasuredSpeedSignedMps  := PRG_02_Acquisition.Data.EncoderM1.Measurement.SignedSpeed_Mps,
    SpeedConfig             := _WinchSpeedConfig,
    LoadTable               := _WinchLoadEstimateTable
);

instWinchLoadEstimatorM2(
    Enable                  := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE) AND NOT PRG_03_Modes_Cycle.Data.Auth.InhibitM2,
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    Mode                    := PRG_03_Modes_Cycle.Data.Auth.Mode,
    ActiveSpeedStep         := instWinchM2.StepNumber,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    MeasuredSpeedMps        := PRG_02_Acquisition.Data.EncoderM2.Measurement.Speed_Mps,
    MeasuredSpeedSignedMps  := PRG_02_Acquisition.Data.EncoderM2.Measurement.SignedSpeed_Mps,
    SpeedConfig             := _WinchSpeedConfig,
    LoadTable               := _WinchLoadEstimateTable
);

// --- M1 : assemblage des structs (CODESYS refuse l'initialiseur inline en appel) ---
// 🔗 Routage permit both : en commande both (WinchBothMotionActive=TRUE), les
// Chaque treuil consomme directement son permis directionnel canonique ; Both est
// validé par l'AND des deux axes dans l'arbitrage.
// jamais les permits individuels directement. En unitaire (M1 seul / M2 seul / benne M2),
// chacun consomme son permit effectif propre (comportement inchangé). SEL(a, b, c) := a ? c : b.
ReqM1Winch.RunRequest               := M1LogicRunRequest;
ReqM1Winch.ReqAscent                := M1LogicReqAscent;
ReqM1Winch.ReqDescend               := M1LogicReqDescend;
ReqM1Winch.SpeedStepReq             := M1LogicRequestStepTgt;
ReqM1Winch.MaxStepUp                := CommonMaxStepAscent;
ReqM1Winch.MaxStepDown              := CommonMaxStepDescent;
// Plancher palier descente plongée Kobold : plancher plongée agrégé en §5ter, injecté
// sur la cible (jamais sur StepNumber). Aucun effet si StartStop=FALSE.
ReqM1Winch.MinStepDown              := CommonMinStepDown;
ReqM1Winch.HomingApproachActive     := PRG_03_Modes_Cycle.Data.Auth.HomingApproachEnable;
// Même limite haute active que FB_Safety_Winch (7,5 m / 8,5 m sous override).
ReqM1Winch.TopLimitM                := TopLimitM1_M;
ReqM1Winch.BottomLimitM             := BottomLimitM1_Active;
ReqM1Winch.SyncCoupled              := instWinchSync.SyncActive;

M1WinchSensors.CablePosM          := PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM;
M1WinchSensors.Homed              := PRG_02_Acquisition.Data.EncoderM1.Homed;
M1WinchSensors.HomingSuspect      := PRG_02_Acquisition.Data.EncoderM1.HomingSuspect;
M1WinchSensors.ContactorsAllOff   := PRG_02_Acquisition.HwIn.Winch.M1_ContactorsReleased_DI;
M1WinchSensors.MeasuredSpeedBand  := instWinchLoadEstimatorM1.SpeedBand;
// Garde-fou vitesse mesuree : DESACTIVE par defaut (AF_Partie-10 §9bis, FB_Winch_v2.1 /
// FB_SpeedStep_v1.0 SpeedGuardEnable := FALSE). Le TRUE code en dur etait un reste de
// mise en service : il rendait la capacite de palier otage de instWinchSync (tout ecart
// sync -> SpeedGuardReady=FALSE -> clamp palier 1, y compris en montee).
// ⚠️ DETTE SAFETY -S5 : le garde-fou vitesse mesuree est HORS SERVICE. Le FB de
// gouvernance nominale annonce (FB_WinchRateInterlock) n'existe PAS dans CODE/.
// Decision : risque ACTE et documente — la surveillance survitesse reelle est portee par
// FB_Safety_Winch (gelee : harnais VAR_IN_OUT indisponible). Ne PAS armer une
// survitesse sur une table non prouvee. A re-trancher a la livraison .
// ⚠️ tache est BLOQUE (contrat C4 TASK_CONTRACT_AUTORITE_2_INTERLOCKS.yaml,
// ARRET VALIDATION HUMAINE requis : autorite, T_max/DropConfirmDelay, classification
// Fault.Error, argument PLr ; prerequis// non livres). Ne PAS creer
// FB_WinchRateInterlock hors de ce contrat — la logique de garde-fou existe deja dans
// FB_Winch §5 et reste volontairement desactivee (SpeedGuardEnable := FALSE) tant que la
// table SpeedBandMaxMps n'est pas validee en charge reelle (AF-10 §7.3 TBD).
M1WinchSensors.SpeedGuardEnable   := FALSE;
M1WinchSensors.SpeedGuardReady    := NOT instWinchSync.Fault.Error;

M1WinchCfg.SpeedStepTable         := _WinchSpeedStepTable;
M1WinchCfg.SlowdownDistanceTop_M  := _CommunCfgPersist.WinchSlowdownDistanceTop_M;
M1WinchCfg.SlowdownDistanceBottom_M := _CommunCfgPersist.WinchSlowdownDistanceBottom_M;
M1WinchCfg.SlowdownMaxStep        := _CommunCfgPersist.WinchSlowdownMaxStep;

instWinchM1(
    Enable                  := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE) AND NOT PRG_03_Modes_Cycle.Data.Auth.InhibitM1,
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    SafeStop                := SafeStopM1_Active,
    DescendPermit           := EffectivePermitM1_Descend,
    AscentPermit            := EffectivePermitM1_Ascent,
    WinchRequest            := ReqM1Winch,
    Sensors                 := M1WinchSensors,
    Config                  := M1WinchCfg,
    // ContactorFeedback (n°3 de la matrice) et Global — sans gate de mode (dérogation MES 2026).
    BypassContactorCheck    := (GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.ContactorFeedback),
    BypassGlobal            := GVL_IHM.M1TreuilRetenue.Bypass.Global
);

// --- M2 : assemblage des structs ---
ReqM2Winch.RunRequest               := M2LogicRunRequest;
ReqM2Winch.ReqAscent                := M2LogicReqAscent;
ReqM2Winch.ReqDescend               := M2LogicReqDescend;
ReqM2Winch.SpeedStepReq             := M2LogicRequestStepTgt;
// Clamp de palier agrégé en §5ter : bornes communes M1=M2 (CommonMaxStep*) puis
// M2-propre (M2MaxStep*) — M2_BucketJogLimit, ManualBucketLimitsActive,
// BucketNotClosedAscentStep1, SlackCableAscentStep1 ne réduisent jamais M1.
// D13 : reconstruction de table M2 supprimée — le clamp M2MaxStep* := 1 suffit
// (StepNumber ≤ 1 → seuls les états P1 sont commandés).
ReqM2Winch.MaxStepUp                := M2MaxStepUp;
ReqM2Winch.MaxStepDown              := M2MaxStepDown;
// Plancher palier descente plongée Kobold : plancher M2-propre agrégé en §5ter, injecté
// sur la cible (jamais sur StepNumber). Aucun effet si StartStop=FALSE.
ReqM2Winch.MinStepDown              := M2MinStepDown;
ReqM2Winch.HomingApproachActive     := PRG_03_Modes_Cycle.Data.Auth.HomingApproachEnable;
// Même limite haute active que FB_Safety_Winch (M2_LimitShift conservé).
ReqM2Winch.TopLimitM                := TopLimitM2_M;
ReqM2Winch.BottomLimitM             := BottomLimitM2_Active;
ReqM2Winch.SyncCoupled              := instWinchSync.SyncActive;

M2WinchSensors.CablePosM          := PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM;
M2WinchSensors.Homed              := PRG_02_Acquisition.Data.EncoderM2.Homed;
M2WinchSensors.HomingSuspect      := PRG_02_Acquisition.Data.EncoderM2.HomingSuspect;
M2WinchSensors.ContactorsAllOff   := PRG_02_Acquisition.HwIn.Winch.M2_ContactorsReleased_DI;
M2WinchSensors.MeasuredSpeedBand  := instWinchLoadEstimatorM2.SpeedBand;
// Garde-fou vitesse mesuree : DESACTIVE par defaut (idem M1 ci-dessus, AF_Partie-10 §9bis).
M2WinchSensors.SpeedGuardEnable   := FALSE;
M2WinchSensors.SpeedGuardReady    := NOT instWinchSync.Fault.Error;

M2WinchCfg.SpeedStepTable         := _WinchSpeedStepTable;
M2WinchCfg.SlowdownDistanceTop_M  := _CommunCfgPersist.WinchSlowdownDistanceTop_M;
M2WinchCfg.SlowdownDistanceBottom_M := _CommunCfgPersist.WinchSlowdownDistanceBottom_M;
M2WinchCfg.SlowdownMaxStep        := _CommunCfgPersist.WinchSlowdownMaxStep;

instWinchM2(
    Enable                  := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE) AND NOT PRG_03_Modes_Cycle.Data.Auth.InhibitM2,
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    SafeStop                := SafeStopM2_Active,
    DescendPermit           := M2DescendPermitApplied,
    AscentPermit            := M2AscentPermitApplied,
    WinchRequest            := ReqM2Winch,
    Sensors                 := M2WinchSensors,
    Config                  := M2WinchCfg,
    // Idem M1 ci-dessus
    BypassContactorCheck    := (GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.ContactorFeedback),
    BypassGlobal            := GVL_IHM.M2TreuilBenne.Bypass.Global
);

// ── Collecteurs passifs d'apprentissage vitesse par palier ──
// Appelés APRÈS instWinchM1/M2 : StepNumber lu = palier courant du scan (pas de lag).
// Dérivations des entrées de collecte :
//   • LoadPresent : charge présente si l'estimateur de charge (même source vitesse) estime
//     une charge >= 50 % (seuil de mise en service, à confirmer sur site).
//   • StableForLearn : treuil commandé (palier > 0) et sans défaut — conditions stables.
// Collecteur STRICTEMENT PASSIF : aucune commande moteur, aucune surveillance survitesse
// (la survitesse reste, gelée — voir bandeau §6 M1/M2 SpeedGuardEnable).
LoadPresentM1 := (instWinchLoadEstimatorM1.EstimatedLoadPct >= 50.0);
LoadPresentM2 := (instWinchLoadEstimatorM2.EstimatedLoadPct >= 50.0);
StableForLearnM1 := (instWinchM1.StepNumber > 0) AND NOT instWinchM1.Fault.Error;
StableForLearnM2 := (instWinchM2.StepNumber > 0) AND NOT instWinchM2.Fault.Error;

instWinchSpeedLearningM1(
    Enable              := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE) AND NOT PRG_03_Modes_Cycle.Data.Auth.InhibitM1,
    LearnStart          := GVL_IHM.M1TreuilRetenue.Cmd.BtnLearnSpeed,
    WinchId             := 1,
    ReqAscent          := M1LogicReqAscent,
    ReqDescend         := M1LogicReqDescend,
    StepNumber          := instWinchM1.StepNumber,
    MeasuredSpeedMps    := PRG_02_Acquisition.Data.EncoderM1.Measurement.Speed_Mps,
    MeasuredSpeedValid  := PRG_02_Acquisition.Data.EncoderM1.Measurement.SpeedValid,
    LoadPresent         := LoadPresentM1,
    StableForLearn      := StableForLearnM1,
    Config              := _WinchSpeedLearnCfg,
    Table               := _WinchSpeedLearnTable
);

instWinchSpeedLearningM2(
    Enable              := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE) AND NOT PRG_03_Modes_Cycle.Data.Auth.InhibitM2,
    LearnStart          := GVL_IHM.M2TreuilBenne.Cmd.BtnLearnSpeed,
    WinchId             := 2,
    ReqAscent          := M2LogicReqAscent,
    ReqDescend         := M2LogicReqDescend,
    StepNumber          := instWinchM2.StepNumber,
    MeasuredSpeedMps    := PRG_02_Acquisition.Data.EncoderM2.Measurement.Speed_Mps,
    MeasuredSpeedValid  := PRG_02_Acquisition.Data.EncoderM2.Measurement.SpeedValid,
    LoadPresent         := LoadPresentM2,
    StableForLearn      := StableForLearnM2,
    Config              := _WinchSpeedLearnCfg,
    Table               := _WinchSpeedLearnTable
);


{endregion}

{region "📤 §7 Publication demandes"}
// === 📤 §7 PUBLICATION DEMANDES BRUTES (WinchM1/M2FinalInterlockRequest) ===

WinchM1FinalInterlockRequest.Enable := TRUE;
WinchM1FinalInterlockRequest.Reset := PRG_07_Supervision.FaultMachineReset_IHM;
WinchM1FinalInterlockRequest.PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI;
WinchM1FinalInterlockRequest.SafeStop := SafeStopM1_Active;
// Plus de BrakeReleaseRequest/
// BrakeCommandOpenConfirmed calcules par FB_Winch — la barriere finale
// (FB_WinchOutputInterlock) recoit le retour PHYSIQUE brut directement,
// et calcule elle-meme BrakeCmd := RelayFwd OR RelayRev (voir bandeau de ce FB).
WinchM1FinalInterlockRequest.BrakeFeedback := PRG_02_Acquisition.HwIn.Winch.M1_BrakeIsOpen_DI;
WinchM1FinalInterlockRequest.FwdRevSpeedFeedbackOff := PRG_02_Acquisition.HwIn.Winch.M1_ContactorsReleased_DI;
WinchM1FinalInterlockRequest.RequestedRelayFwd := instWinchM1.RelayFwd;
WinchM1FinalInterlockRequest.RequestedRelayRev := instWinchM1.RelayRev;
WinchM1FinalInterlockRequest.RequestedContactor1 := instWinchM1.Contactor1;
WinchM1FinalInterlockRequest.RequestedContactor2 := instWinchM1.Contactor2;
WinchM1FinalInterlockRequest.RequestedContactor3 := instWinchM1.Contactor3;
WinchM1FinalInterlockRequest.RequestedContactor4 := instWinchM1.Contactor4;
WinchM1FinalInterlockRequest.RequestedStep := instWinchM1.StepNumber;
WinchM1FinalInterlockRequest.PowerCutOff := instSafetyWinchM1.PowerCutOff;
WinchM1FinalInterlockRequest.AscentPermit := EffectivePermitM1_Ascent;
WinchM1FinalInterlockRequest.DescendPermit := EffectivePermitM1_Descend;

WinchM2FinalInterlockRequest.Enable := TRUE;
WinchM2FinalInterlockRequest.Reset := PRG_07_Supervision.FaultMachineReset_IHM;
WinchM2FinalInterlockRequest.PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI;
WinchM2FinalInterlockRequest.SafeStop := SafeStopM2_Active;
WinchM2FinalInterlockRequest.BrakeFeedback := PRG_02_Acquisition.HwIn.Winch.M2_BrakeIsOpen_DI;
WinchM2FinalInterlockRequest.FwdRevSpeedFeedbackOff := PRG_02_Acquisition.HwIn.Winch.M2_ContactorsReleased_DI;
WinchM2FinalInterlockRequest.RequestedRelayFwd := instWinchM2.RelayFwd;
WinchM2FinalInterlockRequest.RequestedRelayRev := instWinchM2.RelayRev;
WinchM2FinalInterlockRequest.RequestedContactor1 := instWinchM2.Contactor1;
WinchM2FinalInterlockRequest.RequestedContactor2 := instWinchM2.Contactor2;
WinchM2FinalInterlockRequest.RequestedContactor3 := instWinchM2.Contactor3;
WinchM2FinalInterlockRequest.RequestedContactor4 := instWinchM2.Contactor4;
WinchM2FinalInterlockRequest.RequestedStep := instWinchM2.StepNumber;
WinchM2FinalInterlockRequest.PowerCutOff := instSafetyWinchM2.PowerCutOff;
WinchM2FinalInterlockRequest.AscentPermit := M2AscentPermitApplied;
WinchM2FinalInterlockRequest.DescendPermit := M2DescendPermitApplied;

{endregion}

{region "📊 §8 Publication états IHM"}
// === 📤 §8 PUBLICATION ÉTATS IHM (faits publics, lecture seule) ===
// Projection déléguée à FB_WinchStateProjection () : recopie bit-identique
// des sources → WinchM1State/WinchM2State/WinchM1Safety/WinchM2Safety/CableLimitAscent.
// Aucune logique de commande modifiée (non-régression). SyncState/BucketState/
// Benne_IsRoughlyClosed/GLV_IHM restent ici (hors scope du FB).
instWinchStateProjection(
    EncoderM1 := PRG_02_Acquisition.Data.EncoderM1,
    EncoderM2 := PRG_02_Acquisition.Data.EncoderM2,
    WinchM1Ref := instWinchM1,
    WinchM2Ref := instWinchM2,
    SafetyM1 := instSafetyWinchM1,
    SafetyM2 := instSafetyWinchM2,
    InterlockM1 := PRG_06_Outputs.instWinchOutputInterlockM1,
    InterlockM2 := PRG_06_Outputs.instWinchOutputInterlockM2,
    Auth := PRG_03_Modes_Cycle.Data.Auth,
    HwInWinch := PRG_02_Acquisition.HwIn.Winch,
    HwRealWinch := PRG_02_Acquisition.HwReal.Winch,
    M1_PrevSpeed_Mps := M1_PrevSpeed_Mps,
    M2_PrevSpeed_Mps := M2_PrevSpeed_Mps,
    M1LogicRequestSpeedCmd_Pct := M1LogicRequestSpeedCmd_Pct,
    M2LogicRequestSpeedCmd_Pct := M2LogicRequestSpeedCmd_Pct,
    BottomLimitM1_Active := BottomLimitM1_Active,
    BottomLimitM2_Active := BottomLimitM2_Active,
    SafeStopM1_Active := SafeStopM1_Active,
    SafeStopM2_Active := SafeStopM2_Active,
    EffectivePermitM1_Ascent := EffectivePermitM1_Ascent,
    EffectivePermitM1_Descend := EffectivePermitM1_Descend,
    EffectivePermitM2_Ascent := EffectivePermitM2_Ascent,
    EffectivePermitM2_Descend := EffectivePermitM2_Descend,
    M2_LimitShift := M2_LimitShift,
    CfgCableLimitAscent_M := _CommunCfgPersist.CfgCableLimitAscent_M,
    CfgCableLimitDescentM1_M := _WinchM1CfgPersist.CfgCableLimitDescent_M,
    CfgCableLimitDescentM2_M := _WinchM2CfgPersist.CfgCableLimitDescent_M,
    EncoderM1_Operational := PRG_02_Acquisition.Data.Network.EncoderM1.Operational,
    EncoderM2_Operational := PRG_02_Acquisition.Data.Network.EncoderM2.Operational,
    M1PowerCutOffSafetyInfo := PRG_06_Outputs.M1PowerCutOffSafetyInfo,
    M1SafeStopSafetyInfo := PRG_06_Outputs.M1SafeStopSafetyInfo,
    M1BlockedBySafetyInfo := PRG_06_Outputs.M1BlockedBySafetyInfo,
    M2PowerCutOffSafetyInfo := PRG_06_Outputs.M2PowerCutOffSafetyInfo,
    M2SafeStopSafetyInfo := PRG_06_Outputs.M2SafeStopSafetyInfo,
    M2BlockedBySafetyInfo := PRG_06_Outputs.M2BlockedBySafetyInfo
);
WinchM1State := instWinchStateProjection.WinchM1State;
WinchM2State := instWinchStateProjection.WinchM2State;
WinchM1Safety := instWinchStateProjection.WinchM1Safety;
WinchM2Safety := instWinchStateProjection.WinchM2Safety;
CableLimitAscentM1Reached := instWinchStateProjection.CableLimitAscentM1Reached;
CableLimitAscentM2Reached := instWinchStateProjection.CableLimitAscentM2Reached;

SyncState.DeltaPos_M := instWinchSync.SignedDeltaPosM;
SyncState.SyncActive := instWinchSync.SyncActive;
SyncState.SyncWarn := instWinchSync.SyncWarn;
SyncState.SyncDeviationWarn := instWinchSync.SyncDeviationWarn;
SyncState.Ready := instWinchSync.Ready;
SyncState.Error := instWinchSync.Fault.Error;
SyncState.ErrorId := instWinchSync.Fault.ErrorId;
IF instWinchSync.Fault.Error THEN
    SyncState.FBState := E_State.ERROR;
ELSIF instWinchSync.SyncActive THEN
    SyncState.FBState := E_State.BUSY;
ELSE
    SyncState.FBState := E_State.READY;
END_IF;

BucketState.MechState := _BucketState;
BucketState.MechState.ActiveOffsetValid := instBucket.ActiveOffsetValid;
IF instBucket.Fault.Error THEN
    BucketState.FBState := E_State.ERROR;
ELSIF instBucket.Lifecycle.Busy THEN
    BucketState.FBState := E_State.BUSY;
ELSE
    BucketState.FBState := E_State.READY;
END_IF;
BucketState.ActiveOffset_M := instBucket.ActiveOffsetM;
BucketState.M2RunRequest := instBucket.M2_RunRequest;
BucketState.M2ReqAscent := instBucket.M2_ReqAscent;
BucketState.M2ReqDescend := instBucket.M2_ReqDescend;
BucketState.M2BucketJogLimit := instBucket.M2_BucketJogLimit;
BucketState.M2PositionCorrected := PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM - instBucket.ActiveOffsetM;
BucketState.Ready := instBucket.Ready;
BucketState.Busy := instBucket.Lifecycle.Busy;
BucketState.Done := instBucket.Lifecycle.Done;
BucketState.Error := instBucket.Fault.Error;
BucketState.ErrorId := instBucket.Fault.ErrorId;
BucketState.RemainingTravel_M := instBucket.RemainingTravelM;
BucketState.DeltaPosition_M := instBucket.DeltaPosition_M;
BucketState.CloseActive := instBucket.CloseReq;
BucketState.OpenActive := instBucket.OpenReq;
// Reflète le séquencement auto : occupé sur une ouverture/fermeture qu'IL a armée, ou en phase
// vitesse contrôlée post-fermeture.
BucketState.AutoBucketSeqActive := (instBucket.Lifecycle.Busy AND (WinchBothDiveBucketOpenArmed OR WinchBothAscentBucketCloseArmed)) OR ExtractionControlActive;
BucketState.CoupledDiveOpenArmed := WinchBothDiveBucketOpenArmed;
BucketState.CoupledAscentCloseArmed := WinchBothAscentBucketCloseArmed;
BucketState.MachineHomed := PRG_02_Acquisition.Data.MachineHoming.Homed;
BucketState.MachineHomingStep := PRG_02_Acquisition.Data.MachineHoming.Step;
BucketState.MachineHomingInstruction := PRG_02_Acquisition.Data.MachineHoming.Instruction;
BucketState.MachineHomingFailed := PRG_02_Acquisition.Data.MachineHoming.Failed;
BucketState.MachineHomingActive := PRG_02_Acquisition.Data.MachineHoming.Active;
BucketState.MachineHomingLossSafeStop := PRG_02_Acquisition.Data.MachineHoming.HomingLoss;
BucketState.ExtractionControlActive := ExtractionControlActive;
BucketState.CoupledMotionBlockedByBucket := WinchBothMotionBlockedByBucket;
GVL_IHM.Commun.KoboldImmersionConfirmed := KoboldImmersionConfirmed;
GVL_IHM.Commun.KoboldBottomTouchLatched := KoboldBottomTouchLatched;

// Tolérance matière benne : « à peu près fermée » = fermée OU
// intermédiaire proche de l'offset fermé (tolérance 2 m). Évite le blocage au fond sur
// matière dense (galets) qui ne ferme jamais à 100% de la consigne fine.
Benne_IsRoughlyClosed := _BucketState.IsClosed
    OR (_BucketState.IsIntermediate
        AND (instBucket.DeltaPosition_M >= (_BucketCfgPersist.Config.OffsetCloseM - 2.0)));

{region "🕵️ §8bis Trace blocage"}
// === 🕵️ §8bis TRACE DE BLOCAGE TERRAIN (cause priorisée + horodatage) ===
// Diagnostic lecture seule, publié via Data.TraceM1/M2 et consommé par FB_TroubleshootingView.
// L'ordre IF/ELSIF EST l'ordre de priorité (cf. E_WinchTraceBlockReason) : la cause la plus
// grave gagne. BlockReasonTimestamp est latched au premier scan du changement (1 scan, mémoire).
// Aucune action de conduite ne dépend de ces champs.

// --- M1 ---
TraceM1.DescendPermitEffective := EffectivePermitM1_Descend;
TraceM1.AscentPermitEffective  := EffectivePermitM1_Ascent;
TraceM1.AscentPermitApplied     := EffectivePermitM1_Ascent;
TraceM1.DescendPermitApplied    := EffectivePermitM1_Descend;
TraceM1.FinalPermitBlocked      := (ReqM1Winch.RunRequest AND ReqM1Winch.ReqAscent AND NOT EffectivePermitM1_Ascent)
                               OR (ReqM1Winch.RunRequest AND ReqM1Winch.ReqDescend AND NOT EffectivePermitM1_Descend);
TraceM1.SafeStopActive         := SafeStopM1_Active;
TraceM1.SafeStopSourceSafety   := instSafetyWinchM1.SafeStop;
TraceM1.SafeStopSourceInput    := PRG_02_Acquisition.Data.InputModules.Fault
                                  OR PRG_02_Acquisition.Data.MachineHoming.HomingLoss
                                  OR instBucket.M1SlipDetected;
TraceM1.SafeStopSourceSync     := ((instWinchSync.Fault.ErrorId AND 16#0002) <> 16#0000)
                                  OR (instWinchSync.SyncActive AND SafeStopM2_Raw);
TraceM1.PowerCutOffActive      := instSafetyWinchM1.PowerCutOff;
TraceM1.Inhibited              := (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.DISABLE)
                                  OR PRG_03_Modes_Cycle.Data.Auth.InhibitM1;
TraceM1.FinalInterlockError    := WinchM1State.FinalInterlockError;
TraceM1.FinalInterlockReason   := WinchM1State.FinalInterlockReason;
TraceM1.StepNumber             := WinchM1State.StepNumber;

IF instSafetyWinchM1.PowerCutOff THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.POWER_CUTOFF;
ELSIF TraceM1.Inhibited THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.AXIS_DISABLED;
ELSIF SafeStopM1_Active THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.SAFESTOP;
ELSIF instSafetyWinchM1.Fault.Error THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.SAFETY_FAULT;
ELSIF NOT (SafetyPermitM1_Ascent OR SafetyPermitM1_Descend) THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.SAFETY_PERMIT_MISSING;
ELSIF NOT (ProcessPermitM1_Ascent OR ProcessPermitM1_Descend) THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.PROCESS_PERMIT_MISSING;
ELSIF NOT (EffectivePermitM1_Ascent OR EffectivePermitM1_Descend) THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.COUPLING_BLOCKED;
ELSIF instWinchM1.Fault.Error THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.WINCH_FAULT;
ELSIF WinchM1State.FinalInterlockError THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.FINAL_INTERLOCK_BLOCKED;
ELSE
    TraceM1.BlockReason := E_WinchTraceBlockReason.NONE;
END_IF;
IF TraceM1.BlockReason <> TraceM1_PrevReason THEN
    TraceM1.BlockReasonTimestamp := TIME_TO_UDINT(TIME());
END_IF;
TraceM1_PrevReason := TraceM1.BlockReason;

// --- M2 ---
TraceM2.DescendPermitEffective := EffectivePermitM2_Descend;
TraceM2.AscentPermitEffective  := EffectivePermitM2_Ascent;
TraceM2.AscentPermitApplied     := M2AscentPermitApplied;
TraceM2.DescendPermitApplied    := M2DescendPermitApplied;
TraceM2.FinalPermitBlocked      := (ReqM2Winch.RunRequest AND ReqM2Winch.ReqAscent AND NOT EffectivePermitM2_Ascent)
                               OR (ReqM2Winch.RunRequest AND ReqM2Winch.ReqDescend AND NOT EffectivePermitM2_Descend);
TraceM2.SafeStopActive         := SafeStopM2_Active;
TraceM2.SafeStopSourceSafety   := instSafetyWinchM2.SafeStop;
TraceM2.SafeStopSourceInput    := PRG_02_Acquisition.Data.InputModules.Fault
                                  OR PRG_02_Acquisition.Data.MachineHoming.HomingLoss;
TraceM2.SafeStopSourceSync     := ((instWinchSync.Fault.ErrorId AND 16#0002) <> 16#0000)
                                  OR (instWinchSync.SyncActive AND SafeStopM1_Raw);
TraceM2.PowerCutOffActive      := instSafetyWinchM2.PowerCutOff;
TraceM2.Inhibited              := (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.DISABLE)
                                  OR PRG_03_Modes_Cycle.Data.Auth.InhibitM2;
TraceM2.FinalInterlockError    := WinchM2State.FinalInterlockError;
TraceM2.FinalInterlockReason   := WinchM2State.FinalInterlockReason;
TraceM2.StepNumber             := WinchM2State.StepNumber;

IF instSafetyWinchM2.PowerCutOff THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.POWER_CUTOFF;
ELSIF TraceM2.Inhibited THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.AXIS_DISABLED;
ELSIF SafeStopM2_Active THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.SAFESTOP;
ELSIF instSafetyWinchM2.Fault.Error THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.SAFETY_FAULT;
ELSIF NOT (SafetyPermitM2_Ascent OR SafetyPermitM2_Descend) THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.SAFETY_PERMIT_MISSING;
ELSIF NOT (ProcessPermitM2_Ascent OR ProcessPermitM2_Descend) THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.PROCESS_PERMIT_MISSING;
ELSIF NOT (EffectivePermitM2_Ascent OR EffectivePermitM2_Descend) THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.COUPLING_BLOCKED;
ELSIF instWinchM2.Fault.Error THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.WINCH_FAULT;
ELSIF WinchM2State.FinalInterlockError THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.FINAL_INTERLOCK_BLOCKED;
ELSE
    TraceM2.BlockReason := E_WinchTraceBlockReason.NONE;
END_IF;
IF TraceM2.BlockReason <> TraceM2_PrevReason THEN
    TraceM2.BlockReasonTimestamp := TIME_TO_UDINT(TIME());
END_IF;
TraceM2_PrevReason := TraceM2.BlockReason;

{endregion}

// 🧩 Cause de blocage priorisée sur l'état public IHM (miroir de la trace terrain §8bis)
WinchM1State.AxisBlockReason := TraceM1.BlockReason;
WinchM2State.AxisBlockReason := TraceM2.BlockReason;

// === 🔌 PUBLICATION BUS INTER-PRG (Data : ST_WinchInterPrg) ===
// Copie des structs internes vers le bus de sortie (producteur unique).
Data.WinchM1FinalInterlockRequest := WinchM1FinalInterlockRequest;
Data.WinchM2FinalInterlockRequest := WinchM2FinalInterlockRequest;
Data.M1LogicRequestSpeedCmd_Pct   := M1LogicRequestSpeedCmd_Pct;
Data.M2LogicRequestSpeedCmd_Pct   := M2LogicRequestSpeedCmd_Pct;
Data.KoboldContactorCmdArbitrated := KoboldContactorCmdArbitrated;
Data.WinchM1State                 := WinchM1State;
Data.WinchM2State                 := WinchM2State;
Data.WinchM1Safety                := WinchM1Safety;
Data.WinchM2Safety                := WinchM2Safety;
Data.SyncState                    := SyncState;
Data.WinchSyncError               := instWinchSync.Fault.Error;
Data.WinchSyncSignedDeltaPosM     := instWinchSync.SignedDeltaPosM;
Data.BucketState                  := BucketState;
Data.Benne_IsRoughlyClosed        := Benne_IsRoughlyClosed;
Data.BucketBusy                   := instBucket.Lifecycle.Busy;
Data.BucketDone                   := instBucket.Lifecycle.Done;
Data.BucketError                  := instBucket.Fault.Error;
Data.EffectivePermitBucket_Open   := EffectivePermitBucket_Open;
Data.EffectivePermitBucket_Close  := EffectivePermitBucket_Close;
Data.ArmingPermit                 := ArmingPermit;
Data.ProcessPermitM1_Ascent       := ProcessPermitM1_Ascent;
Data.ProcessPermitM1_Descend      := ProcessPermitM1_Descend;
Data.ProcessPermitM2_Ascent       := ProcessPermitM2_Ascent;
Data.ProcessPermitM2_Descend      := ProcessPermitM2_Descend;
Data.DescendPermitDiveBucketOpen  := DescendPermitDiveBucketOpen;
Data.ExtractionAssistActive       := ExtractionAssistActive;
Data.ExtractionAscentPermit       := PRG_03_Modes_Cycle.Data.ReqProgram.ReqBucket.AscentPermit;
// Usage effectif d'un override/bypass de position (consommé PRG_03 → FB_Modes)
Data.PositionLimitOverriddenM1    := PositionLimitOverriddenM1;
Data.PositionLimitOverriddenM2    := PositionLimitOverriddenM2;
// 🕵️ Trace de blocage terrain (consommée FB_TroubleshootingView)
Data.TraceM1                      := TraceM1;
Data.TraceM2                      := TraceM2;
// 🔗 ATOMICITÉ BOTH : diagnostic IHM lecture seule
Data.BothActive                   := WinchBothMotionActive;
Data.BothBlocked                  := BothBlocked;
Data.BothBlockReason              := BothBlockReason;

{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS & REARMEMENT
ResetEdge(CLK := Reset);

IF ResetEdge.Q OR BypassGlobal THEN
    CfgFaultLatched       := FALSE;
    OffsetMaxFaultLatched := FALSE;
    TimeoutFaultLatched   := FALSE;
    M1SlipFaultLatched    := FALSE;
    HomingFaultLatched    := FALSE;
END_IF;

IF NOT BypassGlobal THEN
    // Cause 0 : Configuration géométrie benne
    IF (Config.OffsetOpenM >= Config.OffsetCloseM)
       OR (Config.OffsetOpenM < 0.0) THEN
        CfgFaultLatched := TRUE;
    END_IF;
    instCauses[0].Active   := CfgFaultLatched;
    instCauses[0].Latching := TRUE;
    instCauses[0].Texte    := 'Configuration geometrie benne invalide';

    // Cause 1 : Dépassement écart max
    MaxAllowedOffset := Config.OffsetCloseM + 2.0;
    IF (CablePosM2 > (CablePosM1 + MaxAllowedOffset)) OR (CablePosM2 < CablePosM1) THEN
        OffsetMaxFaultLatched := TRUE;
    END_IF;
    instCauses[1].Active   := OffsetMaxFaultLatched;
    instCauses[1].Latching := TRUE;
    instCauses[1].Texte    := 'Depassement ecart maximum autorise benne';

    // Cause 2 : Timeout
    TonTimeout(IN := Lifecycle.Busy, PT := CfgTimeoutDuration);
    IF TonTimeout.Q THEN
        TimeoutFaultLatched := TRUE;
    END_IF;
    instCauses[2].Active   := TimeoutFaultLatched;
    instCauses[2].Latching := TRUE;
    instCauses[2].Texte    := 'Timeout commande deplacement benne';

    // Cause 3 : Glissement M1
    M1SlipDetected := Lifecycle.Busy AND (ABS(CablePosM1 - M1RefPosM) > M1SlipToleranceM);
    IF M1SlipDetected THEN
        M1SlipFaultLatched := TRUE;
    END_IF;
    instCauses[3].Active   := M1SlipFaultLatched;
    instCauses[3].Latching := TRUE;
    instCauses[3].Texte    := 'Glissement treuil M1 pendant manoeuvre benne';

    // Cause 4 : Non référencé
    IF NOT HomedM1 OR NOT HomedM2 THEN
        HomingFaultLatched := TRUE;
    END_IF;
    instCauses[4].Active   := HomingFaultLatched;
    instCauses[4].Latching := TRUE;
    instCauses[4].Texte    := 'Codeurs treuils non references pour sequence benne';
ELSE
    TonTimeout(IN := FALSE);
    M1SlipDetected := FALSE;
    instCauses[0].Active := FALSE;
    instCauses[1].Active := FALSE;
    instCauses[2].Active := FALSE;
    instCauses[3].Active := FALSE;
    instCauses[4].Active := FALSE;
END_IF;

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate securite"}
// 🛑 2. GATE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    IF Lifecycle.Busy OR CloseReq OR OpenReq THEN
        BucketState.StateIncoherent := TRUE;
    END_IF;
    Ready := FALSE;
    ActiveOffsetValid := FALSE;
    ActiveOffsetM := 0.0;
    DeltaPosition_M := 0.0;
    RemainingTravelM := 0.0;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
    M2_RunRequest := FALSE;
    M2_ReqAscent := FALSE;
    M2_ReqDescend := FALSE;
    M2_BucketJogLimit := FALSE;
    CloseReq := FALSE;
    OpenReq := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Premier cycle & recalage boutons IHM"}
IF FirstCycle THEN
    FirstCycle := FALSE;
    // Une seule position doit être qualifiée au démarrage : ni l'une ni l'autre
    // ou les deux simultanément signifient que la mémorisation n'est pas fiable.
    IF (BucketState.IsOpen AND BucketState.IsClosed)
       OR (NOT BucketState.IsOpen AND NOT BucketState.IsClosed) THEN
        BucketState.StateIncoherent := TRUE;
    END_IF;
END_IF;

// Les confirmations IHM restent les commandes fonctionnelles de référence
// benne, indépendantes du cycle global. Elles ne sont acceptées qu'à l'arrêt
// en maintenance : un front qualifie l'observation visuelle opérateur.
ConfirmOpenEdge(CLK := ConfirmOpenPosition);
IF ConfirmOpenEdge.Q
   AND (Mode = E_Mode.MAINT_N2)
   AND NOT Lifecycle.Busy AND NOT M1_Busy AND NOT M2_Busy THEN
    BucketState.IsOpen := TRUE;
    BucketState.IsClosed := FALSE;
    BucketState.LastPosM2Open := CablePosM2;
    BucketState.StateIncoherent := FALSE;
END_IF;

ConfirmCloseEdge(CLK := ConfirmClosePosition);
IF ConfirmCloseEdge.Q
   AND (Mode = E_Mode.MAINT_N2)
   AND NOT Lifecycle.Busy AND NOT M1_Busy AND NOT M2_Busy THEN
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := TRUE;
    BucketState.LastPosM2Close := CablePosM2;
    BucketState.StateIncoherent := FALSE;
END_IF;

IF MachineHomingCommitOpen AND NOT Lifecycle.Busy THEN
    BucketState.IsOpen := TRUE;
    BucketState.IsClosed := FALSE;
    BucketState.LastPosM2Open := CablePosM2;
    BucketState.StateIncoherent := FALSE;
END_IF;

IF MachineHomingCommitClose AND NOT Lifecycle.Busy THEN
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := TRUE;
    BucketState.LastPosM2Close := CablePosM2;
    BucketState.StateIncoherent := FALSE;
END_IF;
{endregion}

{region "§4 Séquencement mouvement benne"}
SevereError := Fault.Error;
MotionRequestConflict := ReqAscent AND ReqDescend;
MotionRequestActive := (ReqAscent OR ReqDescend) AND NOT MotionRequestConflict;

IF SevereError THEN
    M2_RunRequest := FALSE;
    M2_ReqAscent := FALSE;
    M2_ReqDescend := FALSE;
    M2_BucketJogLimit := FALSE;
    CloseReq := FALSE;
    OpenReq := FALSE;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
ELSE
    // Prise en compte des demandes IHM — anti-traversée (TC-P10-025) :
    // demande benne refusée si un treuil agit (M1_Busy OR M2_Busy) à l'entrée READY.
    IF CmdOpen_IHM AND NOT Lifecycle.Busy AND NOT M1_Busy AND NOT M2_Busy THEN
        OpenReq := TRUE;
        CloseReq := FALSE;
    ELSIF CmdClose_IHM AND NOT Lifecycle.Busy AND NOT M1_Busy AND NOT M2_Busy THEN
        CloseReq := TRUE;
        OpenReq := FALSE;
    END_IF;

    BusyEdge(CLK := (CloseReq OR OpenReq) AND MotionRequestActive);

    IF BusyEdge.Q THEN
        M1RefPosM := CablePosM1;
        M2StartPosM := CablePosM2;
        WasOpenAtStart := BucketState.IsOpen;
        WasClosedAtStart := BucketState.IsClosed;
        LeftStartSinceArm := FALSE;
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
    END_IF;

    IF Lifecycle.Busy THEN
        IF CloseReq THEN
            RemainingTravelM := MAX(0.0, (CablePosM1 + Config.OffsetCloseM) - CablePosM2);
            M2_BucketJogLimit := TRUE;
            IF MotionRequestActive AND ReqAscent AND EffectivePermitBucket_Close THEN
                M2_RunRequest := TRUE;
                M2_ReqAscent := TRUE;
                M2_ReqDescend := FALSE;
            ELSIF MotionRequestActive AND ReqDescend AND EffectivePermitBucket_Open THEN
                M2_RunRequest := TRUE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := TRUE;
            ELSE
                M2_RunRequest := FALSE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := FALSE;
            END_IF;
        ELSIF OpenReq THEN
            RemainingTravelM := MAX(0.0, CablePosM2 - (CablePosM1 + Config.OffsetOpenM));
            M2_BucketJogLimit := TRUE;
            IF MotionRequestActive AND ReqDescend AND EffectivePermitBucket_Open THEN
                M2_RunRequest := TRUE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := TRUE;
            ELSIF MotionRequestActive AND ReqAscent AND EffectivePermitBucket_Close THEN
                M2_RunRequest := TRUE;
                M2_ReqAscent := TRUE;
                M2_ReqDescend := FALSE;
            ELSE
                M2_RunRequest := FALSE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := FALSE;
            END_IF;
        ELSE
            M2_RunRequest := FALSE;
            M2_ReqAscent := FALSE;
            M2_ReqDescend := FALSE;
            M2_BucketJogLimit := FALSE;
        END_IF;

        IF (CloseReq AND (CablePosM2 > M2StartPosM)) OR (OpenReq AND (CablePosM2 < M2StartPosM)) THEN
            LeftStartSinceArm := TRUE;
        END_IF;

        // Arrêt fermeture
        IF CloseReq THEN
            IF CablePosM2 >= (CablePosM1 + Config.OffsetCloseM - Config.CloseAnticipationM) THEN
                M2_RunRequest := FALSE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := FALSE;
                BucketState.IsOpen := FALSE;
                BucketState.IsClosed := TRUE;
                BucketState.LastPosM2Close := CablePosM2;
                BucketState.StateIncoherent := FALSE;
                CloseReq := FALSE;
                Lifecycle.Busy := FALSE;
                Lifecycle.Done := TRUE;
            ELSIF LeftStartSinceArm AND (CablePosM2 <= M2StartPosM) THEN
                M2_RunRequest := FALSE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := FALSE;
                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;
                CloseReq := FALSE;
                Lifecycle.Busy := FALSE;
                Lifecycle.Done := TRUE;
            END_IF;
        END_IF;

        // Arrêt ouverture
        IF OpenReq THEN
            IF CablePosM2 <= (CablePosM1 + Config.OffsetOpenM + Config.OpenAnticipationM) THEN
                M2_RunRequest := FALSE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := FALSE;
                BucketState.IsOpen := TRUE;
                BucketState.IsClosed := FALSE;
                BucketState.LastPosM2Open := CablePosM2;
                BucketState.StateIncoherent := FALSE;
                OpenReq := FALSE;
                Lifecycle.Busy := FALSE;
                Lifecycle.Done := TRUE;
            ELSIF LeftStartSinceArm AND (CablePosM2 >= M2StartPosM) THEN
                M2_RunRequest := FALSE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := FALSE;
                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;
                OpenReq := FALSE;
                Lifecycle.Busy := FALSE;
                Lifecycle.Done := TRUE;
            END_IF;
        END_IF;
    ELSIF Lifecycle.Done THEN
        M2_RunRequest := FALSE;
        M2_ReqAscent := FALSE;
        M2_ReqDescend := FALSE;
        M2_BucketJogLimit := FALSE;
        RemainingTravelM := 0.0;
        IF NOT MotionRequestActive THEN
            Lifecycle.Done := FALSE;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§5 Offset actif et validite"}
DeltaPosition_M := CablePosM2 - CablePosM1;

IF Lifecycle.Busy THEN
    ActiveOffsetM := CablePosM2 - CablePosM1;
    HoldOffsetM := ActiveOffsetM;
ELSIF CloseReq OR BucketState.IsClosed THEN
    ActiveOffsetM := Config.OffsetCloseM;
    HoldOffsetM := ActiveOffsetM;
ELSIF OpenReq OR BucketState.IsOpen THEN
    ActiveOffsetM := Config.OffsetOpenM;
    HoldOffsetM := ActiveOffsetM;
ELSE
    ActiveOffsetM := HoldOffsetM;
END_IF;

ActiveOffsetValid := Enable AND PowerContactorEngaged
                     AND NOT BucketState.StateIncoherent
                     AND (Fault.ErrorId = 0)
                     AND (MachineHomed OR (BucketState.IsOpen XOR BucketState.IsClosed))
                     AND NOT MachineHomingActive;
BucketState.ActiveOffsetValid := ActiveOffsetValid;
{endregion}

// === IMPLEMENTATION ===

Ready := Enable;

IF NOT Enable THEN
    CmdOpen_IHM  := FALSE;
    CmdClose_IHM := FALSE;
    KoboldContactorCmdArbitrated := FALSE;
    WinchBothDiveBucketOpenArmed    := FALSE;
    WinchBothAscentBucketCloseArmed := FALSE;
ELSE
    // ── Règle absolue en pilotage both normal (bit-identique PRG_04 §1) ──
    // Descente autorisée UNIQUEMENT benne ouverte, montée UNIQUEMENT benne fermée.
    WinchBothDiveBucketOpenArmed := Context.TglEnableCoupledBucketSequencing
        AND (Auth.Mode <> E_Mode.SEMI_AUTO)
        AND Context.MotionActive AND Context.ReqDescend
        AND NOT Context.BucketIsOpen;
    WinchBothAscentBucketCloseArmed := Context.TglEnableCoupledBucketSequencing
        AND (Auth.Mode <> E_Mode.SEMI_AUTO)
        AND Context.MotionActive AND Context.ReqAscent
        AND NOT Context.BucketIsClosed;

    // ── Ouverture benne : bouton IHM OU séquencement couplé descente benne ouverte
    //    OU demande cycle (bit-identique PRG_04 §2) ──
    CmdOpen_IHM := IHM.BtnOpen OR WinchBothDiveBucketOpenArmed OR ReqBucket.ReqOpen;

    // ── Fermeture benne : demande cycle > séquencement couplé montée benne fermée
    //    > bouton IHM (bit-identique PRG_04 §1) ──
    IF ReqBucket.ReqClose THEN
        CmdClose_IHM := TRUE;
    ELSIF WinchBothAscentBucketCloseArmed THEN
        CmdClose_IHM := TRUE;
    ELSE
        CmdClose_IHM := IHM.BtnClose;
    END_IF;

    // ── Contacteur Kobold : demande cycle (source unique PRG_03, bit-identique PRG_04 §1) ──
    KoboldContactorCmdArbitrated := ReqBucket.ReqKoboldMeasureEnable;
END_IF;

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS & REARMENT
ResetEdge(CLK := Reset);

IF ResetEdge.Q OR BypassGlobal THEN
    EncoderFaultLatched           := FALSE;
    MotorThermalFaultLatched      := FALSE;
    PhaseRotationFaultLatched     := FALSE;
    MecaAFaultLatched             := FALSE;
    MecaBFaultLatched             := FALSE;
    MecaCFaultLatched             := FALSE;
    BrakeThermalFaultLatched      := FALSE;
    MecaDFaultLatched             := FALSE;
    MecaEFaultLatched             := FALSE;
    MecaEEscaladeFaultLatched     := FALSE;
    OppositeDirectionFaultLatched := FALSE;
    NoMovementFaultLatched        := FALSE;
    OverspeedFaultLatched         := FALSE;
END_IF;

IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    CablePosMPrev                 := CablePosM;
    ExpectedOtherWinchPosMPrev   := ExpectedOtherWinchPosM;
    EncoderFaultLatched           := FALSE;
    MotorThermalFaultLatched      := FALSE;
    PhaseRotationFaultLatched     := FALSE;
    MecaAFaultLatched             := FALSE;
    MecaBFaultLatched             := FALSE;
    MecaCFaultLatched             := FALSE;
    BrakeThermalFaultLatched      := FALSE;
    MecaDFaultLatched             := FALSE;
    MecaEFaultLatched             := FALSE;
    MecaEEscaladeFaultLatched     := FALSE;
    OppositeDirectionFaultLatched := FALSE;
    NoMovementFaultLatched        := FALSE;
    OverspeedFaultLatched         := FALSE;
END_IF;

IF NOT BypassGlobal THEN
    TonStartupWarmup(IN := Enable, PT := T#3s);

    // 🛡️ Fenetre de reference : le preset SDO du codeur (homing, y compris reference benne fermee)
    // fait sauter CablePosM d'un bloc. Sans garde, DriftGuardA voit une derive non commandee (Meca A)
    // et l'ecart M1/M2 depasse la tolerance (Meca E). Le Busy homing seul est trop court (~500ms) :
    // il retombe avant l'application reelle du preset et la reconvergence M1/M2. On maintient donc
    // l'inhibition pendant homing + cycle benne + saut de position detecte + 2s de stabilisation,
    // et on RAZ les latches parasites poses dans le meme scan. Le saut sur ExpectedOtherWinchPosM
    // couvre le cas ou c'est l'AUTRE treuil qui est reference (ce treuil n'est pas en homing).
    // Les autres protections (limites, contacteurs, chaine) restent actives (AF_Partie-09 §13 :
    // le treuil ne passe pas en mode securite degrade, le homing exige l'arret confirme des treuils).
    PosStepDetected := (ABS(CablePosM - CablePosMPrev) > CST_RefPosStepM)
                    OR (ABS(ExpectedOtherWinchPosM - ExpectedOtherWinchPosMPrev) > CST_RefPosStepM);
    CablePosMPrev := CablePosM;
    ExpectedOtherWinchPosMPrev := ExpectedOtherWinchPosM;
    TonRefSettle(IN := NOT (InReferencingMode OR BenneBusy OR PosStepDetected), PT := T#2s);
    RefWindowActive := InReferencingMode OR BenneBusy OR PosStepDetected OR NOT TonRefSettle.Q;
    IF RefWindowActive THEN
        MecaAFaultLatched         := FALSE;
        MecaEFaultLatched         := FALSE;
        MecaEEscaladeFaultLatched := FALSE;
    END_IF;

    // Cause 0 : Perte com opérateur (live)
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassOperatorComm) THEN
        instCauses[0].Active := (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk);
    ELSE
        instCauses[0].Active := FALSE;
    END_IF;
    instCauses[0].Latching := FALSE;
    instCauses[0].Texte    := 'Perte communication operateur treuil';

    // Cause 1 : Perte codeur (latched)
    IF NOT (BypassProcess OR EncoderFaultBypass) AND NOT EncoderAvailable THEN
        EncoderFaultLatched := TRUE;
    END_IF;
    instCauses[1].Active   := EncoderFaultLatched;
    instCauses[1].Latching := TRUE;
    instCauses[1].Texte    := 'Perte ou defaut codeur treuil';

    // Cause 2 : Surchauffe thermique moteur (latched)
    IF NOT (BypassSafety OR BypassMotorThermal) AND ThermalFeedback THEN
        MotorThermalFaultLatched := TRUE;
    END_IF;
    instCauses[2].Active   := MotorThermalFaultLatched;
    instCauses[2].Latching := TRUE;
    instCauses[2].Texte    := 'Surchauffe thermique moteur treuil';

    // Cause 3 : Mou de câble (live / auto-effaçable)
    IF NOT BypassProcess AND SlackCableDetected THEN
        instCauses[3].Active := TRUE;
    ELSE
        instCauses[3].Active := FALSE;
    END_IF;
    instCauses[3].Latching := FALSE;
    instCauses[3].Texte    := 'Detection mou de cable treuil';

    // Cause 4 : Rotation phases (latched)
    IF NOT (BypassProcess OR BypassPhaseRotation) AND NOT PhaseRotationOk THEN
        PhaseRotationFaultLatched := TRUE;
    END_IF;
    instCauses[4].Active   := PhaseRotationFaultLatched;
    instCauses[4].Latching := TRUE;
    instCauses[4].Texte    := 'Defaut rotation de phases treuil';

    // Cause 5 : Fin de course haut capteur (live)
    IF NOT (BypassProcess OR BypassTopLimitSwitch) AND (NOT TopPositionSensor AND NOT InReferencingMode) THEN
        instCauses[5].Active := TRUE;
    ELSE
        instCauses[5].Active := FALSE;
    END_IF;
    instCauses[5].Latching := FALSE;
    instCauses[5].Texte    := 'Fin de course haut capteur atteint';

    // Cause 6 : Limite max câble descente (live)
    IF NOT (BypassProcess OR BypassCableLimitSwitch) AND (CablePosM <= CfgCableLimitDescentM) AND NOT InReferencingMode THEN
        instCauses[6].Active := TRUE;
    ELSE
        instCauses[6].Active := FALSE;
    END_IF;
    instCauses[6].Latching := FALSE;
    instCauses[6].Texte    := 'Limite basse cable atteinte';

    // Cause 7 : Méca A dérive à l'arrêt (latched)
    DriftGuardA(
        Arm        := NOT (BypassSafety OR BypassMecaA) AND FwdRevSpeedFeedbackOff AND NOT BrakeFeedback AND NOT BenneHoldStillActive AND NOT RefWindowActive,
        PositionM  := CablePosM,
        ToleranceM := UncommandedDriftToleranceM
    );
    MecaADriftM := DriftGuardA.DriftM;
    IF DriftGuardA.Violation THEN MecaAFaultLatched := TRUE; END_IF;
    instCauses[7].Active   := MecaAFaultLatched;
    instCauses[7].Latching := TRUE;
    instCauses[7].Texte    := 'Derive non commandee treuil (Meca A)';

    // Cause 8 : Méca B absence confirmation arrêt (latched)
    IF NOT (BypassSafety OR BypassMecaB) THEN
        UncommandedActiveB := JoystickYNeutral AND NOT BenneHoldStillActive AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback);
        TonMecaB(IN := UncommandedActiveB, PT := PostRampTimeout);
        IF TonMecaB.Q THEN MecaBFaultLatched := TRUE; END_IF;
    ELSE
        TonMecaB(IN := FALSE);
    END_IF;
    MecaBElapsedTime := TonMecaB.ET;
    instCauses[8].Active   := MecaBFaultLatched;
    instCauses[8].Latching := TRUE;
    instCauses[8].Texte    := 'Absence confirmation arret contacteurs/frein (Meca B)';

    // Cause 9 : Méca C glissement benne (latched)
    DriftGuardC(
        Arm        := NOT (BypassSafety OR BypassMecaC) AND BenneHoldStillActive,
        PositionM  := CablePosM,
        ToleranceM := BenneSlipToleranceM
    );
    MecaCDriftM := DriftGuardC.DriftM;
    IF DriftGuardC.Violation THEN MecaCFaultLatched := TRUE; END_IF;
    instCauses[9].Active   := MecaCFaultLatched;
    instCauses[9].Latching := TRUE;
    instCauses[9].Texte    := 'Glissement treuil pendant cycle benne (Meca C)';

    // Cause 10 : Surchauffe thermique frein (latched)
    IF NOT (BypassSafety OR BypassBrakeThermal) AND BrakeThermalFeedback THEN
        BrakeThermalFaultLatched := TRUE;
    END_IF;
    instCauses[10].Active   := BrakeThermalFaultLatched;
    instCauses[10].Latching := TRUE;
    instCauses[10].Texte    := 'Surchauffe thermique frein treuil';

    // Cause 11 : Méca D escalade capteur haut (latched)
    IF NOT (BypassSafety OR BypassMecaD) THEN
        UncommandedActiveD := NOT TopPositionSensor AND NOT InReferencingMode AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback);
        TonMecaD(IN := UncommandedActiveD, PT := PostRampTimeout);
        IF TonMecaD.Q THEN MecaDFaultLatched := TRUE; END_IF;
    ELSE
        TonMecaD(IN := FALSE);
    END_IF;
    instCauses[11].Active   := MecaDFaultLatched;
    instCauses[11].Latching := TRUE;
    instCauses[11].Texte    := 'Escalade fin de course haut (Meca D)';

    // Cause 12 & 13 : Méca E écart critique synchro & escalade (latched)
    IF Enable AND NOT (BypassProcess OR BypassMecaE) AND SyncEnable AND NOT RefWindowActive AND NOT OtherWinchInhibited
       AND (ABS(CablePosM - ExpectedOtherWinchPosM) > CriticalSyncToleranceM) THEN
        MecaEFaultLatched := TRUE;
    END_IF;
    instCauses[12].Active   := MecaEFaultLatched;
    instCauses[12].Latching := TRUE;
    instCauses[12].Texte    := 'Ecart critique synchronisation treuil (Meca E)';

    TonMecaE(
        IN := NOT (BypassSafety OR BypassMecaE) AND NOT RefWindowActive AND MecaEFaultLatched AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback),
        PT := PostRampTimeout
    );
    IF TonMecaE.Q THEN MecaEEscaladeFaultLatched := TRUE; END_IF;
    instCauses[13].Active   := MecaEEscaladeFaultLatched;
    instCauses[13].Latching := TRUE;
    instCauses[13].Texte    := 'Escalade ecart synchronisation (Meca E)';

    // Cause 14 : Sens opposé (latched)
    OppositeDirectionActive := NOT BypassProcess AND MeasuredSpeedValid AND (MovementCommanded AND NOT InReferencingMode
        AND ((ReqAscent AND (MeasuredSpeedSignedMps < -MovementSpeedThresholdMps))
          OR (ReqDescend AND (MeasuredSpeedSignedMps > MovementSpeedThresholdMps))));
    TonOppositeDirection(IN := OppositeDirectionActive, PT := OppositeDirectionTimeout);
    IF TonOppositeDirection.Q THEN OppositeDirectionFaultLatched := TRUE; END_IF;
    instCauses[14].Active   := OppositeDirectionFaultLatched;
    instCauses[14].Latching := TRUE;
    instCauses[14].Texte    := 'Sens reel oppose a la commande treuil';

    // Cause 15 : Absence mouvement (latched)
    TonNoMovement(
        IN := NOT BypassProcess AND MeasuredSpeedValid AND (MovementCommanded AND NOT InReferencingMode
              AND (ABS(MeasuredSpeedSignedMps) < MovementSpeedThresholdMps)),
        PT := NoMovementTimeout
    );
    IF TonNoMovement.Q THEN NoMovementFaultLatched := TRUE; END_IF;
    instCauses[15].Active   := NoMovementFaultLatched;
    instCauses[15].Latching := TRUE;
    instCauses[15].Texte    := 'Absence mouvement malgre commande treuil';

    // Survitesse (latch dédié hors bitfield —, alternative validée).
    // Seuil = max bande apprise  (SpeedBandMaxMps). Latché jusqu'au Reset.
    // ⚠️ N'alimente PAS PowerCutOff : couper la puissance en survitesse peut
    // provoquer une chute libre de la charge — décision à trancher (ISO 13849).
    IF NOT BypassProcess AND NOT RefWindowActive AND MeasuredSpeedValid AND (ABS(MeasuredSpeedMps) > SpeedBandMaxMps) THEN
        OverspeedFaultLatched := TRUE;
    END_IF;

ELSE
    TonMecaB(IN := FALSE);
    TonMecaD(IN := FALSE);
    TonMecaE(IN := FALSE);
    TonOppositeDirection(IN := FALSE);
    TonNoMovement(IN := FALSE);
    TonRefSettle(IN := FALSE);
    RefWindowActive := FALSE;
    PosStepDetected := FALSE;
    CablePosMPrev := CablePosM;
    ExpectedOtherWinchPosMPrev := ExpectedOtherWinchPosM;
END_IF;

// ContactorStuck : proprietaire UNIQUE de la detection contacteur colle.
// Escalade : Meca B (bit8) -> SafeStop + PowerCutOff apres PostRampTimeout si le
// collage persiste. Le champ ContactorsCheck.StuckClosed de FB_Winch est force a
// FALSE (Phase 0) ; la re-alimentation IHM/Troubleshooting se fera depuis cette sortie.
ContactorStuck := MecaBFaultLatched;
OverspeedFault := OverspeedFaultLatched;

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

// Miroirs des causes : exactement les bits de la vue LIVE ErrorId (le socle pose
// ErrorId bit i = Causes[i].Active quand Enable). §2 fait RETURN si Enable=FALSE,
// ces miroirs ne servent qu'en aval, sous Enable.
CauseOperatorCommActive   := instCauses[0].Active;
CauseEncoderActive        := instCauses[1].Active;
CauseMotorThermalActive   := instCauses[2].Active;
CauseSlackCableActive     := instCauses[3].Active;
CausePhaseRotationActive  := instCauses[4].Active;
CauseTopLimitSwitchActive := instCauses[5].Active;
CauseCableLimitActive     := instCauses[6].Active;
CauseMecaAActive          := instCauses[7].Active;
CauseMecaBActive          := instCauses[8].Active;
CauseMecaCActive          := instCauses[9].Active;
CauseBrakeThermalActive   := instCauses[10].Active;
CauseMecaDActive          := instCauses[11].Active;
CauseMecaEActive          := instCauses[12].Active;
CauseMecaEEscaladeActive  := instCauses[13].Active;
CauseOppositeDirActive    := instCauses[14].Active;
CauseNoMovementActive     := instCauses[15].Active;

// Agregats safety (causes homogenes, AF03 §4 — jamais de masque hexa) :
// CausesSafeStop : toutes les causes sauf les 3 purement directionnelles
// (SlackCable bit3, TopLimitSwitch bit5, CableLimitDescent bit6), traitees
// par les permis de sens. CausesPowerCutOff : defauts a coupure immediate,
// SANS MecaE-ecart (bit12, laisse au SafeStop tant que non confirme).
CausesSafeStopActive := CauseOperatorCommActive OR CauseEncoderActive
    OR CauseMotorThermalActive OR CausePhaseRotationActive
    OR CauseMecaAActive OR CauseMecaBActive OR CauseMecaCActive
    OR CauseBrakeThermalActive OR CauseMecaDActive
    OR CauseMecaEActive OR CauseMecaEEscaladeActive
    OR CauseOppositeDirActive OR CauseNoMovementActive;

CausesPowerCutOffActive := CauseMotorThermalActive OR CauseMecaAActive
    OR CauseMecaBActive OR CauseMecaCActive OR CauseBrakeThermalActive
    OR CauseMecaDActive OR CauseMecaEEscaladeActive;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    SafeStop := FALSE;
    DescendPermit := FALSE;
    AscentPermit := FALSE;
    PowerCutOff := FALSE;
    TonMecaB(IN := FALSE);
    TonMecaD(IN := FALSE);
    TonMecaE(IN := FALSE);
    TonOppositeDirection(IN := FALSE);
    TonNoMovement(IN := FALSE);
    TonStartupWarmup(IN := FALSE);
    MecaBElapsedTime := T#0s;
    Ready := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Arbitrage sorties securite"}
// 📤 3. ARBITRAGE SÉCURITÉ
// Interlocks sur les miroirs de causes (bits ErrorId) — jamais de masque hexa.
IF NOT PowerContactorEngaged THEN
    SafeStop := TRUE;
ELSE
    // Causes non directionnelles + survitesse. Hors synchro (SyncEnable=FALSE),
    // le mou de cable (bit3) n'entraine pas SafeStop : il bloque la descente
    // seule via DescendPermit (retendre en montant reste possible).
    SafeStop := CausesSafeStopActive
                OR (SyncEnable AND CauseSlackCableActive)
                OR OverspeedFaultLatched;
END_IF;

DescendPermit := NOT (
    ((CauseCableLimitActive OR NOT PowerContactorEngaged) AND NOT (BypassGlobal OR BypassCableLimitSwitch))
    OR ((CablePosM <= CfgCableLimitDescentM) AND NOT InReferencingMode AND NOT BypassCableLimitSwitch)
    // La limite légale est une interdiction d'exploitation distincte du groupe
    // SafeStop/Permit. Le bypass banc BypassProcess ne doit jamais la lever :
    // seul le bypass dédié BypassLimitLegal, déjà filtré par la matrice MAINT_N2
    // dans PRG_04, peut l'autoriser explicitement.
    OR (LimitLegalReached AND NOT BypassLimitLegal)
    OR ((CauseSlackCableActive AND NOT SyncEnable) AND NOT (BypassProcess OR BypassGlobal))
);

AscentPermit := NOT (
    ((CauseTopLimitSwitchActive
    OR (NOT TopPositionSensor AND NOT InReferencingMode))
    AND NOT BypassTopLimitSwitch)
    // TopLimitM porte la relaxation 7,5->8,5 m en override N1 / bypass N2 : la butee
    // logicielle reste active a la valeur relevee. Bypasser le logiciel releve la butee,
    // il ne la supprime pas ; le FDC haut materiel reste une barriere independante.
    OR (Homed AND NOT HomingSuspect AND NOT InReferencingMode AND (CablePosM >= TopLimitM))
);

PowerCutOff := CausesPowerCutOffActive;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS & REARMEMENT
ResetEdge(CLK := Reset);
EnableRisingEdge(CLK := Enable);

IF ResetEdge.Q OR BypassGlobal THEN
    SpeedStepConfigFaultLatched := FALSE;
    ContactorsCheck.StuckClosed := FALSE;
END_IF;

IF Enable AND SpeedStep.ConfigError THEN
    SpeedStepConfigFaultLatched := TRUE;
END_IF;

// FB_Safety_Winch est l'unique proprietaire de la detection contacteur colle.
// FB_Winch conserve le champ public pour compatibilite IHM/Troubleshooting,
// mais ne produit plus ce defaut.
instCauses[1].Active   := FALSE;
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Contacteur colle gere par FB_Safety_Winch ';

instCauses[2].Active   := SpeedStepConfigFaultLatched;
instCauses[2].Latching := TRUE;
instCauses[2].Texte    := 'Configuration table des paliers vitesse invalide';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    SpeedStep(Enable := FALSE, SpeedStepReq := 0, Table := Config.SpeedStepTable);
    DirectionInterlock(Enable := FALSE, EnableRising := FALSE, Reset := Reset, ReqAscent := FALSE, ReqDescend := FALSE,
                       ChangeDelayAscent := Config.DirectionInterlockDelayAscent,
                       ChangeDelayDescent := Config.DirectionInterlockDelayDescent);
    StepShaper(Enable := FALSE, TargetStep := 0, StepRampDelay := Config.StepRampDelayAscent);
    RelayFwd := FALSE;
    RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    RequestedStep := 0;
    StepNumber := StepShaper.ShapedStep;
    CommandedAscent := DirectionInterlock.CommandedAscent;
    CommandedDescend := DirectionInterlock.CommandedDescend;
    RequestConflict := DirectionInterlock.RequestConflict;
    DirectionChangePending := DirectionInterlock.DirectionChangePending;
    TonContactorsDropped(IN := FALSE);
    ContactorsCheck.Command := FALSE;
    ContactorsCheck.Feedback := NOT Sensors.ContactorsAllOff;
    InTopSlowdownZone := FALSE;
    InBottomSlowdownZone := FALSE;
    // §3bis : coupure dure -> aucun maintien de sens possible, etat interne purge.
    SenseHoldRequest := FALSE;
    SenseHoldActiveInt := FALSE;
    SenseHoldTimer(IN := FALSE, PT := T#900ms);
    PrevStepNumber := 0;
    Ready := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Permis et zones de ralentissement"}
DirectionConflict := WinchRequest.ReqAscent AND WinchRequest.ReqDescend;
EffectiveSafeStop := SafeStop OR DirectionConflict
                     OR (WinchRequest.ReqAscent AND NOT AscentPermit)
                     OR (WinchRequest.ReqDescend AND NOT DescendPermit);

InTopSlowdownZone := Sensors.Homed AND NOT Sensors.HomingSuspect AND (Sensors.CablePosM >= (WinchRequest.TopLimitM - Config.SlowdownDistanceTop_M));
InBottomSlowdownZone := Sensors.Homed AND NOT Sensors.HomingSuspect AND (Sensors.CablePosM <= (WinchRequest.BottomLimitM + Config.SlowdownDistanceBottom_M));

IF WinchRequest.ReqAscent AND NOT WinchRequest.ReqDescend THEN
    ActiveMaxStep := WinchRequest.MaxStepUp;
    IF InTopSlowdownZone THEN
        ActiveMaxStep := MIN(ActiveMaxStep, Config.SlowdownMaxStep);
    END_IF;
ELSIF WinchRequest.ReqDescend AND NOT WinchRequest.ReqAscent THEN
    ActiveMaxStep := WinchRequest.MaxStepDown;
    IF InBottomSlowdownZone THEN
        ActiveMaxStep := MIN(ActiveMaxStep, Config.SlowdownMaxStep);
    END_IF;
ELSE
    ActiveMaxStep := WinchRequest.MaxStepUp;
END_IF;

IF WinchRequest.HomingApproachActive THEN
    ActiveMaxStep := 1;
END_IF;
{endregion}

{region "§4 Interlock direction"}
// 🔀 4. INTERLOCK DIRECTION (extrait dans FB_WinchDirectionInterlock, D18)
DirectionInterlock(
    Enable := (StepNumber = 0) AND Sensors.ContactorsAllOff,
    EnableRising := EnableRisingEdge.Q,
    Reset := Reset,
    ReqAscent := WinchRequest.ReqAscent,
    ReqDescend := WinchRequest.ReqDescend,
    ChangeDelayAscent := Config.DirectionInterlockDelayAscent,
    ChangeDelayDescent := Config.DirectionInterlockDelayDescent
);
CommandedAscent := DirectionInterlock.CommandedAscent;
CommandedDescend := DirectionInterlock.CommandedDescend;
RequestConflict := DirectionInterlock.RequestConflict;
DirectionChangePending := DirectionInterlock.DirectionChangePending;
DirectionChangeDelayElapsed := DirectionInterlock.DelayElapsed;
{endregion}

{region "§5 Paliers vitesse et contacteurs"}
// -B : la consigne est désormais un PALIER discret (WinchRequest.SpeedStepReq,
// 1..5, 0 = arrêt) produit par l'arbitrage. Plus de décodage %→palier ici.
IF DirectionChangePending OR NOT (WinchRequest.ReqAscent OR WinchRequest.ReqDescend) OR EffectiveSafeStop OR NOT WinchRequest.RunRequest THEN
    RampTargetStep := 0;
ELSE
    RampTargetStep := WinchRequest.SpeedStepReq;
END_IF;

SpeedStep(
    Enable := (RampTargetStep > 0),
    SpeedStepReq := RampTargetStep,
    Table := Config.SpeedStepTable,
    MaxStepNumber := ActiveMaxStep
);
RequestedStep := SpeedStep.StepNumber;

// 🛡️ Garde-fou vitesse : bride le palier demande si la vitesse n'est pas stable
// (SpeedGuardReady=FALSE -> palier 1) ou si la bande mesuree est inferieure au
// palier demande (pas de passage aux paliers superieurs sans vitesse confirmee).
SpeedGuardLimited := FALSE;
IF Sensors.SpeedGuardEnable THEN
    IF NOT Sensors.SpeedGuardReady THEN
        IF RequestedStep > 1 THEN
            RequestedStep := 1;
            SpeedGuardLimited := TRUE;
        END_IF;
    ELSIF (Sensors.MeasuredSpeedBand >= 1) AND (Sensors.MeasuredSpeedBand <= 5) AND (RequestedStep > Sensors.MeasuredSpeedBand) THEN
        RequestedStep := Sensors.MeasuredSpeedBand;
        SpeedGuardLimited := TRUE;
    END_IF;
END_IF;

// 🤿 Plancher palier descente -- plongee Kobold.
// Injecte MinStepDown sur la CIBLE (RequestedStep, consommee par le shaper ci-dessous),
// JAMAIS sur StepNumber directement. Actif uniquement en descente commandee
// ET NON bloquee par un arret/permis (NOT EffectiveSafeStop) : un permis descente FALSE
// doit interdire physiquement le mouvement, sans re-atterrissage du plancher.
// Le sens doit aussi etre deja adopte : pendant DirectionChangePending, le
// StepNumber doit rester a 0 afin que le temps mort d'inversion puisse s'ecouler.
// (RunRequest AND ReqDescend) : relache joystick (RunRequest=FALSE) -> aucun plancher,
// l'arret franc RequestedStep=0 / RampTargetStep=0 est preserve.
// Regle d'agregation : le PLAFOND GAGNE -- si le plancher depasse le plafond courant
// ActiveMaxStep (ex. SlowdownMaxStep -> palier 1 en bordure basse), on borne au plafond.
IF WinchRequest.RunRequest AND WinchRequest.ReqDescend AND NOT WinchRequest.ReqAscent
   AND (WinchRequest.MinStepDown > 0) AND NOT EffectiveSafeStop
   AND NOT DirectionChangePending AND CommandedDescend THEN
    IF RequestedStep < WinchRequest.MinStepDown THEN
        RequestedStep := WinchRequest.MinStepDown;
    END_IF;
    IF RequestedStep > ActiveMaxStep THEN
        RequestedStep := ActiveMaxStep;
    END_IF;
END_IF;

// ⚙️ Cadencement de palier (extrait dans FB_WinchStepShaper, D10).
// Les deux cadences historiques sont preservees sans reutiliser les delais
// d'interlock direction : 1 s en montee, 500 ms en descente.
IF CommandedDescend THEN
    EffectiveStepRampDelay := Config.StepRampDelayDescent;
ELSE
    EffectiveStepRampDelay := Config.StepRampDelayAscent;
END_IF;
StepShaper(
    Enable := Enable,
    TargetStep := RequestedStep,
    StepRampDelay := EffectiveStepRampDelay
);
StepNumber := StepShaper.ShapedStep;
BusinessStepDelayElapsed := StepShaper.StepDelayElapsed;

IF StepNumber > 0 AND CommandedAscent THEN
    RelayFwd := TRUE;
    RelayRev := FALSE;
ELSIF StepNumber > 0 AND CommandedDescend THEN
    RelayFwd := FALSE;
    RelayRev := TRUE;
ELSE
    RelayFwd := FALSE;
    RelayRev := FALSE;
END_IF;

// 🛡️ FIX contacteurs (audit CONTACTEURS_2026-08-31) + SOLUTION : ré-émettre les
// contacteurs depuis FB_SpeedStep (décodage TABLE ST_SpeedStepTable cumulatif :
// P1=0, P2={K1}, P3={K1,K2}, P4={K1,K2,K3}, P5={K1,K2,K3,K4}) sur le palier SHAPÉ,
// au lieu de l'ancien décodage one-hot exclusif (ContactorN := StepNumber=N) qui
// éteignait les paliers inférieurs et ne couvrait pas le palier 5.
SpeedStep(
    Enable          := (StepNumber > 0),
    SpeedStepReq    := StepNumber,
    Table           := Config.SpeedStepTable,
    MaxStepNumber   := ActiveMaxStep
);
Contactor1 := SpeedStep.Contactor1;
Contactor2 := SpeedStep.Contactor2;
Contactor3 := SpeedStep.Contactor3;
Contactor4 := SpeedStep.Contactor4;

AllContactorsCommandedOff := (NOT RelayFwd) AND (NOT RelayRev)
                             AND (NOT Contactor1) AND (NOT Contactor2) AND (NOT Contactor3) AND (NOT Contactor4);

ContactorsCheck.Command  := NOT AllContactorsCommandedOff;
ContactorsCheck.Feedback := NOT Sensors.ContactorsAllOff;
TonContactorsDropped(IN := FALSE, PT := Config.ContactorFeedbackTimeout);
ContactorsCheck.StuckClosed := FALSE; // force a FALSE (Phase 0) : detection contacteur colle produite par FB_Safety_Winch, re-alimentee a la phase suivante
ContactorsCheck.StuckOpen := FALSE;

IF Fault.Error THEN
    RelayFwd := FALSE;
    RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_IF;
{endregion}

{region "§5bis Intention de maintien du contacteur de sens (§3bis)"}
// Quand le palier temporise StepNumber vient de retomber a 0 alors qu'un sens etait
// commande, FB_Winch DEMANDE a la barriere finale (FB_WinchOutputInterlock) de TENIR
// le contacteur de sens le temps que le moteur ralentisse (inertie). Borne par
// T_hold_internal (garde interne, < MaxSenseHoldTime de la barriere = T#1s).
// Coupures dures -> retombee immediate, jamais de maintien (SafeStop / defaut / perte
// puissance / NOT Enable geree a la gate §2).
SenseHoldHardCut := (NOT PowerContactorEngaged) OR EffectiveSafeStop OR Fault.Error;

IF SenseHoldHardCut THEN
    SenseHoldActiveInt := FALSE;
ELSIF (PrevStepNumber > 0) AND (StepNumber = 0) AND (CommandedAscent OR CommandedDescend) THEN
    SenseHoldActiveInt := TRUE;   // front de chute de palier a 0 avec sens encore actif
END_IF;

// T_hold_internal PROVISOIRE essai site (base physique : inertie moteur + chute de couple) ;
// tenu < MaxSenseHoldTime de FB_WinchOutputInterlock pour que la barriere garde le dernier mot.
SenseHoldTimer(IN := SenseHoldActiveInt, PT := T#900ms);
IF SenseHoldTimer.Q OR (StepNumber > 0) THEN
    SenseHoldActiveInt := FALSE;  // borne de temps atteinte, ou nouveau mouvement demande
END_IF;

SenseHoldRequest := SenseHoldActiveInt AND NOT SenseHoldHardCut;
PrevStepNumber := StepNumber;
{endregion}

// === IMPLEMENTATION ===

Ready := Enable;

// Front de fin d'action benne (détecté en interne, mécanisme de sécurité)
BenneBusyFallEdge(CLK := Context.BucketBusy);

IF NOT Enable THEN
    RunRequest := FALSE;
    ReqAscent  := FALSE;
    ReqDescend := FALSE;
    StepTgt   := 0;
ELSE
    // ── Pont SEMI_AUTO : consomme la demande du séquenceur de cycle ──
    IF Auth.Mode = E_Mode.SEMI_AUTO THEN
        RunRequest := ReqWinch.RunRequest;
        ReqAscent  := ReqWinch.ReqAscent;
        ReqDescend := ReqWinch.ReqDescend;
        StepTgt   := ReqWinch.StepTgt;
    ELSE
        // ── Mode manuel : commande both issue de l'intention UNIQUE PRG_03 (BothIntent),
        //    commande unitaire M1 dérivée des boutons/joystick (Select=1). ──
        // 🪜 StepTgt : le joystick est le producteur UNIQUE du palier (FB_Joystick §6).
        //    Boutons/both = pleine vitesse (100 % → palier 5) ; joystick = passthrough
        //    de Joystick.AxisY.StepTgt. Plus de re-dérivation %→palier ici.
        IF NOT TglJoystickMaster THEN
            // Mode Boutons IHM
            IF BothIntent.Active THEN
                // Both (BtnWinchBothAscent/Descent) — source unique PRG_03, plus de re-dérivation
                ReqAscent  := BothIntent.ReqAscent;
                ReqDescend := BothIntent.ReqDescend;
                StepTgt   := Cfg.BtnStepTgt;   // 100 % → palier max (configurable)
            ELSIF IHM.BtnAscentM1 THEN
                ReqAscent  := TRUE;
                ReqDescend := FALSE;
                StepTgt   := Cfg.BtnStepTgt;
            ELSIF IHM.BtnDescentM1 THEN
                ReqAscent  := FALSE;
                ReqDescend := TRUE;
                StepTgt   := Cfg.BtnStepTgt;
            ELSE
                ReqAscent  := FALSE;
                ReqDescend := FALSE;
                StepTgt   := 0;
            END_IF;
        ELSE
            // Mode Joystick Maître — M1 unitaire si Select = 1, both si Select = 0
            IF Auth.JoystickWinchSelectArbitrated = 1 THEN
                ReqAscent  := Joystick.AxisY.Direction > 0;
                ReqDescend := Joystick.AxisY.Direction < 0;
                StepTgt   := Joystick.AxisY.StepTgt;
            ELSIF BothIntent.Active THEN
                // Both (Select=0) — source unique PRG_03, plus de re-dérivation
                ReqAscent  := BothIntent.ReqAscent;
                ReqDescend := BothIntent.ReqDescend;
                StepTgt   := Joystick.AxisY.StepTgt;
            ELSE
                ReqAscent  := FALSE;
                ReqDescend := FALSE;
                StepTgt   := 0;
            END_IF;
        END_IF;

        // Gating StartStop (bit-identique PRG_04 §3) — homme-mort qualifié en joystick
        // 🔗 Atomicité Both : en commande both, la commande ne consomme QUE le
        // permit agrégé (BothAscentPermit/BothDescendPermit) du sens demandé — jamais
        // un permit individuel. Si l'un des 2 treuils n'a pas son permit effectif,
        // AUCUN des deux ne part (départ jamais isolé). En unitaire (BothIntent inactif),
        // le gate est neutre.
        RequestConflict := ReqAscent AND ReqDescend;
        BothDirectionAuthorized := (NOT BothIntent.Active)
            OR ((ReqAscent AND NOT ReqDescend) AND Context.M1AscentAllowed AND Context.M2AscentAllowed)
            OR ((ReqDescend AND NOT ReqAscent) AND Context.M1DescendAllowed AND Context.M2DescendAllowed);
        RunRequest := (ReqAscent OR ReqDescend) AND NOT RequestConflict
                  AND NOT Context.BucketBusy
                  AND NOT Context.WinchBothMotionBlockedByBucket
                  AND NOT ((Context.SyncBlocksAscent   AND ReqAscent)
                        OR (Context.SyncBlocksDescent AND ReqDescend))
                  AND (NOT TglJoystickMaster OR Joystick.DeadmanArmed)
                  AND BothDirectionAuthorized;
    END_IF;

    // Front de fin d'action benne : arrêt forcé sauf mouvement both actif
    IF BenneBusyFallEdge.Q AND NOT (BothIntent.Active AND (BothIntent.ReqAscent OR BothIntent.ReqDescend)) THEN
        RunRequest := FALSE;
    END_IF;
END_IF;

// === IMPLEMENTATION ===

Ready := Enable;

// Front de fin d'action benne (détecté en interne, mécanisme de sécurité)
BenneBusyFallEdge(CLK := Context.BucketBusy);

IF NOT Enable THEN
    RunRequest := FALSE;
    ReqAscent  := FALSE;
    ReqDescend := FALSE;
    StepTgt   := 0;
ELSE
    // ── Chemin benne : M2 piloté par l'action benne (override) ──
    IF Context.BucketBusy AND Context.BucketM2RunRequest THEN
        RunRequest := Context.BucketM2RunRequest;
        ReqAscent  := Context.BucketM2ReqAscent;
        ReqDescend := Context.BucketM2ReqDescend;
        StepTgt   := Cfg.BucketOverrideStepTgt;   // override benne = vitesse lente (palier configurable)
    ELSE
        // ── Pont SEMI_AUTO : consomme la demande du séquenceur de cycle ──
        IF Auth.Mode = E_Mode.SEMI_AUTO THEN
            RunRequest := ReqWinch.RunRequest;
            ReqAscent  := ReqWinch.ReqAscent;
            ReqDescend := ReqWinch.ReqDescend;
            StepTgt   := ReqWinch.StepTgt;
        ELSE
            // ── Mode manuel : commande both issue de l'intention UNIQUE PRG_03 (BothIntent),
            //    commande unitaire M2 dérivée des boutons/joystick (Select=2). ──
            // 🪜 StepTgt : le joystick est le producteur UNIQUE du palier (FB_Joystick §6).
            //    Boutons/both = pleine vitesse (100 % → palier 5) ; joystick = passthrough
            //    de Joystick.AxisY.StepTgt. Plus de re-dérivation %→palier ici.
            IF NOT TglJoystickMaster THEN
                // Mode Boutons IHM
                IF BothIntent.Active THEN
                    // Both (BtnWinchBothAscent/Descent) — source unique PRG_03, plus de re-dérivation
                    ReqAscent  := BothIntent.ReqAscent;
                    ReqDescend := BothIntent.ReqDescend;
                    StepTgt   := Cfg.BtnStepTgt;   // 100 % → palier max (configurable)
                ELSIF IHM.BtnAscentM2 THEN
                    ReqAscent  := TRUE;
                    ReqDescend := FALSE;
                    StepTgt   := Cfg.BtnStepTgt;
                ELSIF IHM.BtnDescentM2 THEN
                    ReqAscent  := FALSE;
                    ReqDescend := TRUE;
                    StepTgt   := Cfg.BtnStepTgt;
                ELSE
                    ReqAscent  := FALSE;
                    ReqDescend := FALSE;
                    StepTgt   := 0;
                END_IF;
            ELSE
                // Mode Joystick Maître — M2 unitaire si Select = 2, both si Select = 0
                IF Auth.JoystickWinchSelectArbitrated = 2 THEN
                    ReqAscent  := Joystick.AxisY.Direction > 0;
                    ReqDescend := Joystick.AxisY.Direction < 0;
                    StepTgt   := Joystick.AxisY.StepTgt;
                ELSIF BothIntent.Active THEN
                    // Both (Select=0) — source unique PRG_03, plus de re-dérivation
                    ReqAscent  := BothIntent.ReqAscent;
                    ReqDescend := BothIntent.ReqDescend;
                    StepTgt   := Joystick.AxisY.StepTgt;
                ELSE
                    ReqAscent  := FALSE;
                    ReqDescend := FALSE;
                    StepTgt   := 0;
                END_IF;
            END_IF;

            // Gating StartStop (bit-identique PRG_04 §3) — synchro INVERSÉE vs M1,
            // homme-mort qualifié en joystick
            // 🔗 Atomicité Both : cf. M1 — en both, la commande ne consomme QUE le
            // permit agrégé du sens demandé. Départ jamais isolé entre les 2 treuils.
            RequestConflict := ReqAscent AND ReqDescend;
            BothDirectionAuthorized := (NOT BothIntent.Active)
                OR ((ReqAscent AND NOT ReqDescend) AND Context.M1AscentAllowed AND Context.M2AscentAllowed)
                OR ((ReqDescend AND NOT ReqAscent) AND Context.M1DescendAllowed AND Context.M2DescendAllowed);
            RunRequest := (ReqAscent OR ReqDescend) AND NOT RequestConflict
                      AND NOT Context.WinchBothMotionBlockedByBucket
                      AND NOT ((Context.SyncBlocksAscent   AND ReqDescend)
                            OR (Context.SyncBlocksDescent AND ReqAscent))
                      AND (NOT TglJoystickMaster OR Joystick.DeadmanArmed)
                      AND BothDirectionAuthorized;
        END_IF;
    END_IF;

    // Front de fin d'action benne : arrêt forcé sauf mouvement both actif
    IF BenneBusyFallEdge.Q AND NOT (BothIntent.Active AND (BothIntent.ReqAscent OR BothIntent.ReqDescend)) THEN
        RunRequest := FALSE;
    END_IF;
END_IF;

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS
ResetEdge(CLK := Reset);

IF ResetEdge.Q AND (MeasuredSpeedMps >= 0.0) THEN
    ConfigOrSpeedFault := FALSE;
END_IF;

instCauses[0].Active   := ConfigOrSpeedFault;
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Parametrage ou vitesse estimation charge invalide';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE;
    SpeedBand := 0;
    EstimatedLoadPct := 0.0;
    Configured := FALSE;
    Ascending := FALSE;
    HasPreviousBand := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
Configured := LoadTable.IsConfigured;
Ascending := (MeasuredSpeedSignedMps > 0.0);
{endregion}

{region "§3 Classement vitesse"}
// 📏 3. CLASSEMENT DE LA VITESSE — hystérésis autour des 4 frontières.
IF (MeasuredSpeedMps < 0.0) OR (SpeedConfig.MaxMeasuredSpeedMps <= 0.0) THEN
    ConfigOrSpeedFault := TRUE;
    SpeedBand := 0;
ELSIF NOT HasPreviousBand THEN
    IF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[1] THEN
        PreviousSpeedBand := 1;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[2] THEN
        PreviousSpeedBand := 2;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[3] THEN
        PreviousSpeedBand := 3;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[4] THEN
        PreviousSpeedBand := 4;
    ELSE
        PreviousSpeedBand := 5;
    END_IF;
    HasPreviousBand := TRUE;
    SpeedBand := PreviousSpeedBand;
ELSE
    IF PreviousSpeedBand < 1 OR PreviousSpeedBand > 5 THEN
        PreviousSpeedBand := 1;
        ConfigOrSpeedFault := TRUE;
    END_IF;

    IF PreviousSpeedBand < 5 THEN
        IF MeasuredSpeedMps > (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand]
                               + SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand + 1;
        END_IF;
    END_IF;
    IF PreviousSpeedBand > 1 THEN
        IF MeasuredSpeedMps < (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand - 1]
                               - SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand - 1;
        END_IF;
    END_IF;
    SpeedBand := PreviousSpeedBand;
END_IF;
{endregion}

{region "§4 Lecture table"}
// 📊 4. LECTURE TABLE
EstimatedLoadPct := 0.0;
IF Configured THEN
    IF Ascending THEN
        IF ActiveSpeedStep >= 1 THEN
            IF ActiveSpeedStep <= 5 THEN
                IF SpeedBand >= 1 THEN
                    IF SpeedBand <= 5 THEN
                        SelectedLoadPct := LoadTable.LoadPctByStepAndSpeedBand[ActiveSpeedStep][SpeedBand];
                        IF (SelectedLoadPct < 0.0) OR (SelectedLoadPct > 100.0) THEN
                            ConfigOrSpeedFault := TRUE;
                        ELSE
                            EstimatedLoadPct := SelectedLoadPct;
                        END_IF;
                    END_IF;
                END_IF;
            END_IF;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§1 Gate et conditions de collecte"}
Ready := Enable;
Learning := FALSE;
LampLearn := FALSE;

// Conditions de collecte scindees (lisibilite Watch, <=3 termes par predicat)
LearnRequested := Enable AND LearnStart;
MeasureUsable := MeasuredSpeedValid AND StableForLearn;
SensConflict := ReqAscent AND ReqDescend;
SensActive := (ReqAscent OR ReqDescend) AND NOT SensConflict;
StepInRange := (StepNumber >= 1) AND (StepNumber <= CST_PalierCount);
AxeInRange := (WinchId >= 1) AND (WinchId <= CST_AxeCount);
ContextValid := SensActive AND StepInRange AND AxeInRange;
CollectAllowed := LearnRequested AND MeasureUsable AND ContextValid;
{endregion}

{region "§2 Collecte passive"}
IF CollectAllowed THEN
    // Index sens et charge
    IF ReqAscent THEN SensIdx := CST_IdxAscent; ELSE SensIdx := CST_IdxDescent; END_IF;
    IF LoadPresent THEN ChargeIdx := CST_IdxCharge; ELSE ChargeIdx := CST_IdxVide; END_IF;

    // Plausibilite : vitesse dans l'enveloppe du palier (borne min/max)
    SpeedPlausible := (MeasuredSpeedMps >= Config.MinSpeedMps[StepNumber])
                      AND (MeasuredSpeedMps <= Config.MaxSpeedMps[StepNumber]);

    CurrentCell := Table.Cell[WinchId, SensIdx, ChargeIdx, StepNumber];
    IF SpeedPlausible THEN
        // Accumulation (moyenne glissante)
        IF CurrentCell.SampleCount = 0 THEN
            CurrentCell.SpeedMps := MeasuredSpeedMps;
            CurrentCell.SampleCount := 1;
        ELSE
            CurrentCell.SpeedMps := (CurrentCell.SpeedMps * UDINT_TO_REAL(CurrentCell.SampleCount) + MeasuredSpeedMps)
                                    / UDINT_TO_REAL(CurrentCell.SampleCount + 1);
            CurrentCell.SampleCount := CurrentCell.SampleCount + 1;
        END_IF;
        CurrentCell.Valid := (CurrentCell.SampleCount >= Config.MinSamples);
    ELSE
        // Valeur hors enveloppe -> cellule invalidee
        CurrentCell.Valid := FALSE;
        CurrentCell.SampleCount := 0;
        CurrentCell.SpeedMps := 0.0;
    END_IF;
    Table.Cell[WinchId, SensIdx, ChargeIdx, StepNumber] := CurrentCell;

    Learning := TRUE;
    LampLearn := TRUE;
END_IF;
{endregion}

{region "§3 Comptage et completude"}
CellsTotal := CST_AxeCount * CST_SensCount * CST_ChargeCount * CST_PalierCount;
CellsFilled := 0;
FOR AxeIdx := 1 TO CST_AxeCount DO
    FOR SensLoopIdx := 1 TO CST_SensCount DO
        FOR ChargeLoopIdx := 1 TO CST_ChargeCount DO
            FOR PalierIdx := 1 TO CST_PalierCount DO
                IF Table.Cell[AxeIdx, SensLoopIdx, ChargeLoopIdx, PalierIdx].Valid THEN
                    CellsFilled := CellsFilled + 1;
                END_IF;
            END_FOR;
        END_FOR;
    END_FOR;
END_FOR;
TableComplete := (CellsFilled >= CellsTotal);
{endregion}

// ═══════════════════════════════════════════════════════════════════════════
// 📊 PROJECTION ÉTATS IHM (recopie bit-identique de la §8 de PRG_04)
// ═══════════════════════════════════════════════════════════════════════════

// ── M1 : état public ────────────────────────────────────────────────────────
// SpeedDelta_Mps = variation de vitesse ENTRE DEUX SCANS (ST_WinchState.st),
// pas un écart M1/M2 (qui existe via SyncStateHMI.DeltaPos_M/instWinchSync).
// Delta temporel via mémoire scan précédent.
WinchM1State.MeasuredSpeed_Mps := EncoderM1.Measurement.Speed_Mps;
WinchM1State.SpeedDelta_Mps    := EncoderM1.Measurement.Speed_Mps - M1_PrevSpeed_Mps;
M1_PrevSpeed_Mps := EncoderM1.Measurement.Speed_Mps;

WinchM1State.Position_M := EncoderM1.Measurement.CablePosM;
WinchM1State.SpeedCmd_Pct := M1LogicRequestSpeedCmd_Pct;
WinchM1State.StepNumber := WinchM1Ref.StepNumber;
IF WinchM1Ref.Fault.Error THEN
    WinchM1State.FBState := E_State.ERROR;
ELSIF WinchM1Ref.StepNumber > 0 THEN
    WinchM1State.FBState := E_State.BUSY;
ELSE
    WinchM1State.FBState := E_State.READY;
END_IF;
WinchM1State.Ready := WinchM1Ref.Ready;
WinchM1State.Busy := (WinchM1Ref.StepNumber > 0);
WinchM1State.Done := FALSE;
WinchM1State.Error := WinchM1Ref.Fault.Error;
WinchM1State.ErrorId := WinchM1Ref.Fault.ErrorId;
WinchM1State.RelayFwd := WinchM1Ref.RelayFwd;
WinchM1State.RelayRev := WinchM1Ref.RelayRev;
WinchM1State.Contactor1 := WinchM1Ref.Contactor1;
WinchM1State.Contactor2 := WinchM1Ref.Contactor2;
WinchM1State.Contactor3 := WinchM1Ref.Contactor3;
WinchM1State.Contactor4 := WinchM1Ref.Contactor4;
WinchM1State.BrakeCmd := InterlockM1.BrakeCmd;
WinchM1State.BrakeCommandOpenConfirmed := HwInWinch.M1_BrakeIsOpen_DI;
WinchM1State.FinalAuthorizedStep := WinchM1Ref.RequestedStep;
WinchM1State.ContactorsCheck := WinchM1Ref.ContactorsCheck;
WinchM1State.FinalInterlockState := InterlockM1.State;
WinchM1State.FinalInterlockReason := InterlockM1.Reason;
WinchM1State.FinalInterlockError := InterlockM1.Fault.Error;
WinchM1State.FinalInterlockErrorId := InterlockM1.Fault.ErrorId;
WinchM1State.FinalRestartInhibit := InterlockM1.RestartInhibit;
WinchM1State.FinalBrakeTimeoutElapsed := InterlockM1.BrakeTimeoutElapsed;
WinchM1State.FinalRestartDelayElapsed := InterlockM1.RestartDelayElapsed;
WinchM1State.FinalStepDelayElapsed := InterlockM1.StepDelayElapsed;
WinchM1State.Encoder.RawPos := EncoderM1.Measurement.RawPos;
WinchM1State.Encoder.Alarms := HwRealWinch.COD1_Alarms;
WinchM1State.Encoder.Warnings := HwRealWinch.COD1_Warnings;
WinchM1State.Encoder.SlaveOperational := EncoderM1_Operational;
WinchM1State.Encoder.PresetTriggerCmd := EncoderM1.HwOut.PresetTriggerCmd;
WinchM1State.Encoder.PresetValueOut := EncoderM1.HwOut.PresetValueOut;
WinchM1State.Encoder.Error := EncoderM1.Measurement.AbsFault.Error;
WinchM1State.Encoder.ErrorId := EncoderM1.Measurement.AbsFault.ErrorId;
WinchM1State.Encoder.Homed := EncoderM1.Homed;
WinchM1State.Encoder.HomingBusy := EncoderM1.Measurement.HomingLifecycle.Busy;
WinchM1State.Encoder.HomingDone := EncoderM1.Measurement.HomingLifecycle.Done;
WinchM1State.Encoder.HomingError := EncoderM1.Measurement.HomingFault.Error;
WinchM1State.Encoder.HomingErrorId := EncoderM1.Measurement.HomingFault.ErrorId;
WinchM1State.Encoder.HomingState := E_State.READY;
WinchM1State.Encoder.HomingStateAtError := E_State.DISABLED;
WinchM1State.Encoder.HomingSuspect := EncoderM1.HomingSuspect;
WinchM1State.Encoder.HomingRefRaw := EncoderM1.Measurement.HomingRefRaw;
WinchM1State.InhibitActive := Auth.InhibitM1;
WinchM1State.BottomLimitActiveM := BottomLimitM1_Active;
WinchM1State.InTopSlowdownZone := WinchM1Ref.InTopSlowdownZone;
WinchM1State.InBottomSlowdownZone := WinchM1Ref.InBottomSlowdownZone;
WinchM1State.CommandedAscent := WinchM1Ref.CommandedAscent;
WinchM1State.CommandedDescend := WinchM1Ref.CommandedDescend;
WinchM1State.DirectionChangeDelayElapsed := WinchM1Ref.DirectionChangeDelayElapsed;
WinchM1State.DirectionChangePending := WinchM1Ref.DirectionChangePending;

// ── M2 : état public (voir bandeau M1 ci-dessus) ────────────────────────────
WinchM2State.MeasuredSpeed_Mps := EncoderM2.Measurement.Speed_Mps;
WinchM2State.SpeedDelta_Mps    := EncoderM2.Measurement.Speed_Mps - M2_PrevSpeed_Mps;
M2_PrevSpeed_Mps := EncoderM2.Measurement.Speed_Mps;

WinchM2State.Position_M := EncoderM2.Measurement.CablePosM;
WinchM2State.SpeedCmd_Pct := M2LogicRequestSpeedCmd_Pct;
WinchM2State.StepNumber := WinchM2Ref.StepNumber;
IF WinchM2Ref.Fault.Error THEN
    WinchM2State.FBState := E_State.ERROR;
ELSIF WinchM2Ref.StepNumber > 0 THEN
    WinchM2State.FBState := E_State.BUSY;
ELSE
    WinchM2State.FBState := E_State.READY;
END_IF;
WinchM2State.Ready := WinchM2Ref.Ready;
WinchM2State.Busy := (WinchM2Ref.StepNumber > 0);
WinchM2State.Done := FALSE;
WinchM2State.Error := WinchM2Ref.Fault.Error;
WinchM2State.ErrorId := WinchM2Ref.Fault.ErrorId;
WinchM2State.RelayFwd := WinchM2Ref.RelayFwd;
WinchM2State.RelayRev := WinchM2Ref.RelayRev;
WinchM2State.Contactor1 := WinchM2Ref.Contactor1;
WinchM2State.Contactor2 := WinchM2Ref.Contactor2;
WinchM2State.Contactor3 := WinchM2Ref.Contactor3;
WinchM2State.Contactor4 := WinchM2Ref.Contactor4;
WinchM2State.BrakeCmd := InterlockM2.BrakeCmd;
WinchM2State.BrakeCommandOpenConfirmed := HwInWinch.M2_BrakeIsOpen_DI;
WinchM2State.FinalAuthorizedStep := WinchM2Ref.RequestedStep;
WinchM2State.ContactorsCheck := WinchM2Ref.ContactorsCheck;
WinchM2State.FinalInterlockState := InterlockM2.State;
WinchM2State.FinalInterlockReason := InterlockM2.Reason;
WinchM2State.FinalInterlockError := InterlockM2.Fault.Error;
WinchM2State.FinalInterlockErrorId := InterlockM2.Fault.ErrorId;
WinchM2State.FinalRestartInhibit := InterlockM2.RestartInhibit;
WinchM2State.FinalBrakeTimeoutElapsed := InterlockM2.BrakeTimeoutElapsed;
WinchM2State.FinalRestartDelayElapsed := InterlockM2.RestartDelayElapsed;
WinchM2State.FinalStepDelayElapsed := InterlockM2.StepDelayElapsed;
WinchM2State.Encoder.RawPos := EncoderM2.Measurement.RawPos;
WinchM2State.Encoder.Alarms := HwRealWinch.COD2_Alarms;
WinchM2State.Encoder.Warnings := HwRealWinch.COD2_Warnings;
WinchM2State.Encoder.SlaveOperational := EncoderM2_Operational;
WinchM2State.Encoder.PresetTriggerCmd := EncoderM2.HwOut.PresetTriggerCmd;
WinchM2State.Encoder.PresetValueOut := EncoderM2.HwOut.PresetValueOut;
WinchM2State.Encoder.Error := EncoderM2.Measurement.AbsFault.Error;
WinchM2State.Encoder.ErrorId := EncoderM2.Measurement.AbsFault.ErrorId;
WinchM2State.Encoder.Homed := EncoderM2.Homed;
WinchM2State.Encoder.HomingBusy := EncoderM2.Measurement.HomingLifecycle.Busy;
WinchM2State.Encoder.HomingDone := EncoderM2.Measurement.HomingLifecycle.Done;
WinchM2State.Encoder.HomingError := EncoderM2.Measurement.HomingFault.Error;
WinchM2State.Encoder.HomingErrorId := EncoderM2.Measurement.HomingFault.ErrorId;
WinchM2State.Encoder.HomingState := E_State.READY;
WinchM2State.Encoder.HomingStateAtError := E_State.DISABLED;
WinchM2State.Encoder.HomingSuspect := EncoderM2.HomingSuspect;
WinchM2State.Encoder.HomingRefRaw := EncoderM2.Measurement.HomingRefRaw;
WinchM2State.InhibitActive := Auth.InhibitM2;
WinchM2State.BottomLimitActiveM := BottomLimitM2_Active;
WinchM2State.InTopSlowdownZone := WinchM2Ref.InTopSlowdownZone;
WinchM2State.InBottomSlowdownZone := WinchM2Ref.InBottomSlowdownZone;
WinchM2State.CommandedAscent := WinchM2Ref.CommandedAscent;
WinchM2State.CommandedDescend := WinchM2Ref.CommandedDescend;
WinchM2State.DirectionChangeDelayElapsed := WinchM2Ref.DirectionChangeDelayElapsed;
WinchM2State.DirectionChangePending := WinchM2Ref.DirectionChangePending;

// ── Limite haute atteinte (fait public) ──────────────────────────────────────
// ⛔️ Miroir de la butée logicielle de AscentPermit (Homed, hors homing, non
// suspect, position >= limite). Fait pur "Reached", sans bypass.
CableLimitAscentM1Reached := EncoderM1.Homed
    AND NOT EncoderM1.HomingSuspect
    AND NOT EncoderM1.Measurement.HomingLifecycle.Busy
    AND (EncoderM1.Measurement.CablePosM >= CfgCableLimitAscent_M);
CableLimitAscentM2Reached := EncoderM2.Homed
    AND NOT EncoderM2.HomingSuspect
    AND NOT EncoderM2.Measurement.HomingLifecycle.Busy
    AND (EncoderM2.Measurement.CablePosM >= (CfgCableLimitAscent_M + M2_LimitShift));

// ── M1 : sécurités publiques ────────────────────────────────────────────────
WinchM1Safety.CableLimitAscent := CableLimitAscentM1Reached;
WinchM1Safety.CableLimitDescent := (EncoderM1.Measurement.CablePosM <= CfgCableLimitDescentM1_M);
WinchM1Safety.SafeStop := SafeStopM1_Active;
WinchM1Safety.AscentPermit := EffectivePermitM1_Ascent;
WinchM1Safety.DescendPermit := EffectivePermitM1_Descend;
WinchM1Safety.ThermalFault := NOT HwInWinch.M1_ThermalOk_DI;
WinchM1Safety.PowerCutOff := SafetyM1.PowerCutOff;
WinchM1Safety.Error := WinchM1Ref.Fault.Error OR SafetyM1.Fault.Error;
WinchM1Safety.ErrorId := SafetyM1.Fault.ErrorId;
WinchM1Safety.LatchedId := SafetyM1.Fault.LatchedId;
WinchM1Safety.ErrorOperatorComm  := (SafetyM1.Fault.ErrorId AND 16#0001) <> 0;
WinchM1Safety.ErrorEncoder       := (SafetyM1.Fault.ErrorId AND 16#0002) <> 0;
WinchM1Safety.ErrorPhaseRotation := (SafetyM1.Fault.ErrorId AND 16#0010) <> 0;
WinchM1Safety.ErrorBrakeThermal  := (SafetyM1.Fault.ErrorId AND 16#0400) <> 0;
WinchM1Safety.ErrorMecaA         := (SafetyM1.Fault.ErrorId AND 16#0080) <> 0;
WinchM1Safety.ErrorMecaB         := (SafetyM1.Fault.ErrorId AND 16#0100) <> 0;
WinchM1Safety.ErrorMecaC         := (SafetyM1.Fault.ErrorId AND 16#0200) <> 0;
WinchM1Safety.ErrorMecaD         := (SafetyM1.Fault.ErrorId AND 16#0800) <> 0;
WinchM1Safety.ErrorMecaE         := (SafetyM1.Fault.ErrorId AND 16#3000) <> 0;
WinchM1Safety.ErrorOppositeDir   := (SafetyM1.Fault.ErrorId AND 16#4000) <> 0;
WinchM1Safety.ErrorNoMovement    := (SafetyM1.Fault.ErrorId AND 16#8000) <> 0;
WinchM1Safety.PowerCutOffSafety  := M1PowerCutOffSafetyInfo;
WinchM1Safety.SafeStopSafety     := M1SafeStopSafetyInfo;
WinchM1Safety.BlockedBySafety    := M1BlockedBySafetyInfo;

// ── M2 : sécurités publiques ───────────────────────────────────────────────
WinchM2Safety.CableLimitAscent := CableLimitAscentM2Reached;
WinchM2Safety.CableLimitDescent := (EncoderM2.Measurement.CablePosM <= CfgCableLimitDescentM2_M);
WinchM2Safety.SafeStop := SafeStopM2_Active;
WinchM2Safety.AscentPermit := EffectivePermitM2_Ascent;
WinchM2Safety.DescendPermit := EffectivePermitM2_Descend;
WinchM2Safety.SlackCable := NOT HwInWinch.M2_TensionedCable_DI;
WinchM2Safety.ThermalFault := NOT HwInWinch.M2_ThermalOk_DI;
WinchM2Safety.PowerCutOff := SafetyM2.PowerCutOff;
WinchM2Safety.Error := WinchM2Ref.Fault.Error OR SafetyM2.Fault.Error;
WinchM2Safety.ErrorId := SafetyM2.Fault.ErrorId;
WinchM2Safety.LatchedId := SafetyM2.Fault.LatchedId;
WinchM2Safety.ErrorOperatorComm  := (SafetyM2.Fault.ErrorId AND 16#0001) <> 0;
WinchM2Safety.ErrorEncoder       := (SafetyM2.Fault.ErrorId AND 16#0002) <> 0;
WinchM2Safety.ErrorPhaseRotation := (SafetyM2.Fault.ErrorId AND 16#0010) <> 0;
WinchM2Safety.ErrorBrakeThermal  := (SafetyM2.Fault.ErrorId AND 16#0400) <> 0;
WinchM2Safety.ErrorMecaA         := (SafetyM2.Fault.ErrorId AND 16#0080) <> 0;
WinchM2Safety.ErrorMecaB         := (SafetyM2.Fault.ErrorId AND 16#0100) <> 0;
WinchM2Safety.ErrorMecaC         := (SafetyM2.Fault.ErrorId AND 16#0200) <> 0;
WinchM2Safety.ErrorMecaD         := (SafetyM2.Fault.ErrorId AND 16#0800) <> 0;
WinchM2Safety.ErrorMecaE         := (SafetyM2.Fault.ErrorId AND 16#3000) <> 0;
WinchM2Safety.ErrorOppositeDir   := (SafetyM2.Fault.ErrorId AND 16#4000) <> 0;
WinchM2Safety.ErrorNoMovement    := (SafetyM2.Fault.ErrorId AND 16#8000) <> 0;
WinchM2Safety.PowerCutOffSafety  := M2PowerCutOffSafetyInfo;
WinchM2Safety.SafeStopSafety     := M2SafeStopSafetyInfo;
WinchM2Safety.BlockedBySafety    := M2BlockedBySafetyInfo;

// === IMPLEMENTATION ===

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable THEN
    Ready := FALSE;
    DeltaPosM := 0.0; SignedDeltaPosM := 0.0;
    SyncActive := FALSE;
    SyncWarn := FALSE; SyncDeviationWarn := FALSE; SyncDeviationFault := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
{endregion}

{region "§2 Activation synchro"}
// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🎚️ 3. SyncActive SELON MODE (Partie9 §9)
CASE Mode OF
    E_Mode.MAINT_N1:
        SyncActive := TRUE;                  // Imposée, non désactivable (sécurité maintenue N1)
    E_Mode.MAINT_N2:
        SyncActive := SyncEnable;             // Polarité positive (TRUE = synchro active)
    ELSE
        SyncActive := TRUE;                  // MANUEL/SEMI_AUTO : actif par prudence
END_CASE;
{endregion}

{region "§3 Sous-blocs deviation et contacteurs"}
// 📏 4. ÉCART CODEURS (FB_SyncDeviation) + COHERENCE CONTACTEURS (FB_SyncContactor)
instDeviation(
    Enable               := Enable,
    Reset                := Reset,
    SyncEnable           := SyncActive,
    CablePosM1           := CablePosM1,
    CablePosM2           := CablePosM2,
    HomedAndReliableM1   := HomedAndReliableM1,
    HomedAndReliableM2   := HomedAndReliableM2,
    CfgSyncToleranceM    := CfgSyncToleranceM,
    CfgSyncCriticalToleranceM := CfgSyncCriticalToleranceM,
    ActiveOffsetM        := ActiveOffsetM,
    BypassGlobal         := BypassGlobal
);
DeltaPosM := instDeviation.DeltaPosM;
SignedDeltaPosM := instDeviation.SignedDeltaPosM;
SyncDeviationWarn := instDeviation.SyncDeviationWarn;
SyncDeviationFault := instDeviation.SyncDeviationFault;

instContactor(
    Enable          := Enable,
    Reset           := Reset,
    SyncEnable      := SyncActive,
    RelayFwdM1      := RelayFwdM1,
    RelayFwdM2      := RelayFwdM2,
    RelayRevM1      := RelayRevM1,
    RelayRevM2      := RelayRevM2,
    Contactor1_M1   := Contactor1_M1,
    Contactor1_M2   := Contactor1_M2,
    Contactor2_M1   := Contactor2_M1,
    Contactor2_M2   := Contactor2_M2,
    Contactor3_M1   := Contactor3_M1,
    Contactor3_M2   := Contactor3_M2,
    Contactor4_M1   := Contactor4_M1,
    Contactor4_M2   := Contactor4_M2,
    BypassGlobal    := BypassGlobal
);
{endregion}

{region "§4 Causes & Socle Défaut"}
IF NOT BypassGlobal THEN
    instCauses[0].Active   := instDeviation.SyncDeviationWarn;
    instCauses[0].Latching := FALSE;
    instCauses[0].Texte    := 'Alerte ecart synchronisation M1/M2';

    instCauses[1].Active   := instContactor.ContactorMismatch;
    instCauses[1].Latching := TRUE;
    instCauses[1].Texte    := 'Discordance contacteurs treuils M1/M2';

    instCauses[2].Active   := instDeviation.SyncDeviationFault;
    instCauses[2].Latching := TRUE;
    instCauses[2].Texte    := 'Ecart critique synchronisation treuils M1/M2';
ELSE
    instCauses[0].Active := FALSE;
    instCauses[1].Active := FALSE;
    instCauses[2].Active := FALSE;
END_IF;

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

SyncWarn := Fault.Error;
Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§1 Reset (front, toujours effectif)"}
// Front Reset : efface tous les latches. Jamais conditionné, agit même Enable=FALSE (§9).
Ready := Enable;
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    FOR i := 0 TO 15 DO Latch[i] := FALSE; END_FOR;
END_IF;
{endregion}

{region "§2 Vue LIVE — Error / ErrorId"}
// Bitfield des causes présentes MAINTENANT. Retombe seule à 0 quand les causes disparaissent.
// Non évaluée si Enable=FALSE (pas de lecture de cause hors autorisation).
Fault.ErrorId := 0;
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active THEN
            Fault.ErrorId := Fault.ErrorId OR SHL(WORD#1, INT_TO_DWORD(i));
        END_IF;
    END_FOR;
END_IF;
Fault.Error := (Fault.ErrorId <> 0);
{endregion}

{region "§3 Armement des latches (causes à acquitter)"}
// Une cause Active ET Latching arme son bit ; le bit reste jusqu'au front Reset (§1),
// même si la cause disparaît. Réapparition => ré-armement (ré-alarme).
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active AND Causes[i].Latching THEN
            Latch[i] := TRUE;
        END_IF;
    END_FOR;
END_IF;
{endregion}

{region "§4 Vue LATCHÉE — Latched / LatchedId"}
// Toujours publiée, y compris Enable=FALSE : un défaut non acquitté reste visible.
Fault.LatchedId := 0;
FOR i := 0 TO 15 DO
    IF Latch[i] THEN
        Fault.LatchedId := Fault.LatchedId OR SHL(WORD#1, INT_TO_DWORD(i));
    END_IF;
END_FOR;
Fault.Latched := (Fault.LatchedId <> 0);
{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_DriftGuard) ===

IF Arm THEN
    IF NOT WasArmed THEN
        RefPosM := PositionM;   // Capture au 1er cycle armé uniquement
        WasArmed := TRUE;
    END_IF;
    DriftM := ABS(PositionM - RefPosM);
    Violation := DriftM > ToleranceM;
ELSE
    WasArmed := FALSE;
    DriftM := 0.0;
    Violation := FALSE;
END_IF;

{region "§0 Bornes et validation table"}
// Le plafond est borné avant le plancher : si le plancher demandé dépasse le
// plafond de sécurité, celui-ci garde la priorité.
_MaxStepClamped := LIMIT(1, MaxStepNumber, 5);
_MinStepClamped := LIMIT(1, MinStepNumber, _MaxStepClamped);

// Les seuils restent validés pour conserver le diagnostic table historique.
// Ils ne participent plus au calcul du palier dans ce FB.
_ConfigValid := TRUE;
_ConfigErrorIdInt := 16#0000;
IF NOT (Table.StepThreshold_Pct[1] < Table.StepThreshold_Pct[2] AND
        Table.StepThreshold_Pct[2] < Table.StepThreshold_Pct[3] AND
        Table.StepThreshold_Pct[3] < Table.StepThreshold_Pct[4] AND
        Table.StepThreshold_Pct[4] < Table.StepThreshold_Pct[5]) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;
IF (Table.StepThreshold_Pct[1] < 0.0) OR (Table.StepThreshold_Pct[5] > 100.0) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;
ConfigErrorId := _ConfigErrorIdInt;
ConfigError := (ConfigErrorId <> 16#0000);
{endregion}

{region "§1 Gate"}
// Relâche ou table invalide : aucun plancher ne peut maintenir un contacteur.
IF (NOT Enable) OR (NOT _ConfigValid) OR (SpeedStepReq <= 0) THEN
    StepNumber := 0;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Clamp et table contacteurs"}
// Le plancher agit sur la cible. StepNumber ne reçoit jamais directement
// MinStepNumber ; LIMIT final garantit la plage 1..5 après le plafond.
StepNumber := LIMIT(_MinStepClamped, SpeedStepReq, _MaxStepClamped);

CASE StepNumber OF
    1:  Contactor1 := Table.P1R1; Contactor2 := Table.P1R2; Contactor3 := Table.P1R3; Contactor4 := Table.P1R4;
    2:  Contactor1 := Table.P2R1; Contactor2 := Table.P2R2; Contactor3 := Table.P2R3; Contactor4 := Table.P2R4;
    3:  Contactor1 := Table.P3R1; Contactor2 := Table.P3R2; Contactor3 := Table.P3R3; Contactor4 := Table.P3R4;
    4:  Contactor1 := Table.P4R1; Contactor2 := Table.P4R2; Contactor3 := Table.P4R3; Contactor4 := Table.P4R4;
    5:  Contactor1 := Table.P5R1; Contactor2 := Table.P5R2; Contactor3 := Table.P5R3; Contactor4 := Table.P5R4;
ELSE
    // Défense en profondeur face à une divergence type/outil.
    StepNumber := 0;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_CASE;
{endregion}

// === IMPLEMENTATION ===

// Front Reset : purge la memoire de direction (un acquittement conscient reinitialise
// l'historique, une reprise apres Reset est un depart propre, pas une inversion).
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    LastAscent := FALSE;
    LastDescend := FALSE;
    CommandedAscent := FALSE;
    CommandedDescend := FALSE;
    DeadTimeArmed := FALSE;
    DirectionChangePending := FALSE;
END_IF;

RequestConflict := ReqAscent AND ReqDescend;
RequestActive := (ReqAscent OR ReqDescend) AND NOT RequestConflict;

// Délai effectif selon le sens demandé
IF ReqAscent AND NOT ReqDescend THEN
    EffectiveDelay := ChangeDelayAscent;
ELSE
    EffectiveDelay := ChangeDelayDescent;
END_IF;

DirectionChanged := (ReqAscent AND NOT CommandedAscent)
                 OR (ReqDescend AND NOT CommandedDescend)
                 OR (CommandedAscent AND NOT ReqAscent)
                 OR (CommandedDescend AND NOT ReqDescend);

// D18 : au front montant Enable avec sens maintenu, armer le temps mort
// (ne pas re-adopter le sens immediatement — pas de redemarrage inrush).
IF EnableRising AND RequestActive THEN
    DeadTimeArmed := TRUE;
END_IF;

// Temporisation : compte quand un changement de sens est demande et treuil arrete
DirectionChangeDelay(
    IN := Enable AND RequestActive AND DirectionChanged,
    PT := EffectiveDelay
);
DelayElapsed := DirectionChangeDelay.ET;

// Adoption du sens
IF NOT RequestActive THEN
    // Neutre ou double demande : aucun sens commandé. Une double demande est
    // explicitement refusée, sans priorité implicite.
    CommandedAscent := FALSE;
    CommandedDescend := FALSE;
    DirectionChangePending := FALSE;
    DeadTimeArmed := FALSE;
ELSIF DeadTimeArmed THEN
    // D18 : temps mort au front Enable — pas d'adoption immediate
    DirectionChangePending := TRUE;
ELSIF DirectionChangeDelay.Q THEN
    // Temps mort ecoule : adoption du sens
    CommandedAscent := ReqAscent;
    CommandedDescend := ReqDescend;
    DirectionChangePending := FALSE;
    DeadTimeArmed := FALSE;
ELSIF NOT (CommandedAscent OR CommandedDescend) THEN
    // Depuis le neutre : depart immediat si reprise du MEME sens (ou premier sens),
    // sinon (sens oppose) pending + delai dedie obligatoire.
    IF (NOT (LastAscent OR LastDescend))
       OR (ReqAscent AND LastAscent)
       OR (ReqDescend AND LastDescend) THEN
        CommandedAscent := ReqAscent;
        CommandedDescend := ReqDescend;
        DirectionChangePending := FALSE;
    ELSE
        DirectionChangePending := TRUE;
    END_IF;
ELSIF DirectionChanged THEN
    // Inversion directe (sans passage au neutre) : pending + delai
    DirectionChangePending := TRUE;
ELSE
    DirectionChangePending := FALSE;
END_IF;

// Memorise le dernier sens non nul ADOPTE (pas la simple demande) : c'est ce sens qui
// sert de reference pour detecter une reprise opposee apres passage au neutre.
IF CommandedAscent OR CommandedDescend THEN
    LastAscent := CommandedAscent;
    LastDescend := CommandedDescend;
END_IF;

// === IMPLEMENTATION ===

IF NOT Enable THEN
    ShapedStep := 0;
    StepDelay(IN := FALSE);
    StepDelayElapsed := T#0s;
    RETURN;
END_IF;

// Temporisation : compte quand la cible est au-dessus du palier courant
StepDelay(
    IN := (TargetStep > ShapedStep) AND (ShapedStep > 0),
    PT := StepRampDelay
);
StepDelayElapsed := StepDelay.ET;

// Cadencement asymetrique : montee +1 cran / StepRampDelay, descente immediate
IF TargetStep = 0 THEN
    ShapedStep := 0;
ELSIF TargetStep < ShapedStep THEN
    ShapedStep := TargetStep;
ELSIF TargetStep > ShapedStep THEN
    IF ShapedStep = 0 THEN
        ShapedStep := 1;
    ELSIF StepDelay.Q THEN
        ShapedStep := ShapedStep + 1;
    END_IF;
END_IF;

// ── 1. FRONT RESET AVANT GATE ───────────────────────────────────────────
// Le front est échantillonné même pendant Enable/AU faux : un Reset maintenu
// pendant une gate ne devient jamais un faux acquittement au retour.
ResetEdge(CLK := Reset);

// ── 2. GATE : neutralisation sûre ───────────────────────────────────────
// ErrorId, RestartInhibit et ResetRequired ne sont jamais effacés par une perte
// Enable/AU : celle-ci coupe uniquement les sorties. Le retour exige toujours un
// acquittement conscient puis une nouvelle demande opérateur.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    BrakeTimeout(IN := FALSE, PT := T#500ms);
    StepDelay(IN := FALSE, PT := T#1s250ms);
    RestartDelay(IN := FALSE, PT := T#1000ms);
    DeadTime(IN := FALSE);
    DeadTimePending := FALSE;
    DeadTimeElapsed := T#0ms;
    // 🔒 Transitoires §3bis neutralisés à la gate (latches de sûreté conservés ci-dessous).
    SenseHoldActive := FALSE; SenseHoldDone := FALSE;
    SenseHoldTimer(IN := FALSE); SenseHoldFeedbackTimer(IN := FALSE);
    SenseHoldElapsed := T#0ms;
    ContactorStuck := ContactorStuckLatched;
    ReleaseOrderActive := FALSE; ReleaseOrderDone := FALSE;
    ReleaseOrderTimer(IN := FALSE, PT := ReleaseOrderDelay);
    ReleaseOrderElapsed := T#0ms;
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    BrakeCmd := FALSE; AuthorizedStep := 0;
    BrakeTimeoutElapsed := T#0ms; RestartDelayElapsed := T#0ms; StepDelayElapsed := T#0ms;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    Error := (ErrorId <> 16#0000);
    State := E_WinchFinalInterlockState.DISABLED;
    RestartRequired := TRUE;
    // 🔒 Sorties de diagnostic et latches de sûreté VOLONTAIREMENT conservés hors Enable (AC3 / §9) :
    // - ErrorId & RestartInhibit : latches défaut et anti-redémarrage auto (doivent survivre à la perte d'Enable, acquittement conscient requis)
    // - StateAtError & Reason : snapshot d'état et cause de blocage préservés pour diagnostic IHM
    RETURN;
END_IF;

RequestedStepClamped := LIMIT(0, RequestedStep, 5);
// 🛡️ SafeStop : coupure dure à la barrière finale (défense en profondeur).
// SafeStop est consommé en §5 : quand TRUE, RelayFwd/Rev, contacteurs et frein
// sont coupés indépendamment de FB_Winch. Enable reste actif (≠ neutralisation) ;
// SafeStop n'est pas un défaut (pas de FAULT, pas de latch, pas de Reset requis).
MotorRequest := (RequestedStepClamped > 0) AND (RequestedRelayFwd XOR RequestedRelayRev);
// Defense en profondeur : le meme permis directionnel que celui applique en amont
// doit encore autoriser la sortie finale. Aucun latch ni defaut n'est cree ici :
// la demande est simplement neutralisee tant que le permis est FALSE.
PermitFinalBlocked := (RequestedRelayFwd AND NOT AscentPermit)
                   OR (RequestedRelayRev AND NOT DescendPermit);

// ── 2bis. Arbitrage Error/ErrorId AVANT §3/§5 ────────────────────────────
// ErrorId bit0 (défaut frein) est mis à jour en FIN de scan (§6bis, après BrakeCmd) —
// la valeur lue ici est donc celle de la fin du scan PRÉCÉDENT (retard d'un scan sur une
// nouvelle occurrence, ~10ms, négligeable face au budget 500ms du watchdog). Voir bandeau.
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// ── 3. Réarmement anti-redémarrage automatique ──────────────────────────
// Après timeout : cause disparue + front Reset, puis demande moteur à zéro,
// puis nouvelle demande distincte. La retombée + T#1000ms sera ensuite refaite.
IF RestartInhibit AND NOT Error AND NOT ResetRequired AND NOT ResetEdge.Q THEN
    IF NOT MotorRequest THEN
        NeutralRequestSeen := TRUE;
        RestartRequired := TRUE;
    ELSIF NeutralRequestSeen AND MotorRequest THEN
        RestartInhibit := FALSE;
        NeutralRequestSeen := FALSE;
        RestartRequired := TRUE;
        Reason := E_WinchFinalInterlockReason.NONE;
    END_IF;
END_IF;

// ── 4. Mémorisation de l'arrêt : temporisation d'anti-redémarrage chaud ──────────
// La temporisation RestartDelay (1500ms) s'arme à l'arrêt du mouvement (NOT MotorRequest) et
// s'écoule pendant la pause à l'arrêt (au lieu de repartir de zéro à chaque nouvel appui) —
// permet un redémarrage instantané si la pause dépasse 1.5s. Le décompte ne démarre/continue que
// si le moteur n'est plus demandé ET que le frein est physiquement confirmé fermé
// (NOT BrakeFeedback = bobine retombée, mâchoires serrées). Garde le comportement "purge pendant
// la pause" (RestartRequired ne s'arme qu'à NOT MotorRequest, indépendant de la tempo).
IF NOT MotorRequest THEN
    RestartRequired := TRUE;
END_IF;
RestartDelay(IN := RestartRequired AND NOT MotorRequest AND NOT BrakeFeedback AND NOT RestartInhibit, PT := T#1500ms);
RestartDelayElapsed := RestartDelay.ET;
IF RestartDelay.Q THEN
    RestartRequired := FALSE;
END_IF;

// ── 4bis. Temps mort directionnel (TC-P10-021/022) ─────────────────────────────
// Distinct du RestartDelay (anti-court-cycle uniforme) : temps mort de redémarrage
// après arrêt, dépendant du sens de la nouvelle demande. Même sens → DeadTimeSameDir ;
// inversion → DeadTimeOppositeDir. Neutre↔sens = immédiat (pas de temps mort à l'armement).
// Le décompte se fait pendant la pause ET pendant l'attente après nouvelle demande
// (purge pendant la pause, comme RestartDelay). PT = DeadTimeOppositeDir (le plus long) ;
// à la nouvelle demande, on vérifie si le temps mort requis pour le sens réel est déjà
// écoulé (cas même sens, plus court).
IF MotorRequest THEN
    IF RequestedRelayFwd THEN
        LastDirection := 1;
    ELSE
        LastDirection := -1;
    END_IF;
END_IF;

IF NOT MotorRequest THEN
    DeadTimePending := TRUE;
END_IF;

DeadTime(IN := DeadTimePending AND NOT BrakeFeedback AND NOT RestartInhibit, PT := DeadTimeOppositeDir);
DeadTimeElapsed := DeadTime.ET;
IF DeadTime.Q THEN
    DeadTimePending := FALSE;
END_IF;

IF MotorRequest AND DeadTimePending THEN
    IF RequestedRelayFwd THEN
        NewDirection := 1;
    ELSE
        NewDirection := -1;
    END_IF;
    IF NewDirection = LastDirection THEN
        RequiredDeadTime := DeadTimeSameDir;
    ELSE
        RequiredDeadTime := DeadTimeOppositeDir;
    END_IF;
    IF DeadTime.ET >= RequiredDeadTime THEN
        DeadTimePending := FALSE;
    END_IF;
END_IF;

// ── 4ter. Maintien borné du contacteur de sens (§3bis) — AC6/AC7/AC8 ─────────
// Règle §3bis : quand RequestedStep retombe à 0 mais RequestedRelayFwd/Rev reste
// TRUE (demande transitoire de chute de palier portée par FB_Winch), la barrière NE
// force PLUS RelayFwd/Rev à FALSE immédiatement — elle TIENT le contacteur de sens
// (jamais relâché avant les contacteurs de vitesse) jusqu'à :
//   - FwdRevSpeedFeedbackOff confirmé, debounced par DropConfirmDelay (AC7 : pas
//     d'ouverture du sens sur retour simple voie seul) ; OU
//   - T_max (MaxSenseHoldTime) écoulé -> chute du sens FORCÉE + latch ContactorStuck.
// Le maintien indéfini du stator sous tension est INTERDIT (AC7). Les coupures dures
// (NOT Enable / PowerContactorEngaged=FALSE / Error / RestartInhibit) ne passent
// JAMAIS par ce maintien (AC9) : elles coupent RelayFwd/Rev immédiatement.
SenseHoldRequested := (RequestedStepClamped = 0) AND (RequestedRelayFwd OR RequestedRelayRev)
                      AND NOT Error AND NOT RestartInhibit AND NOT ContactorStuckLatched;

IF NOT Enable OR NOT PowerContactorEngaged THEN
    // 🔒 Gate dur : pas de maintien possible (les sorties sont déjà coupées §2).
    SenseHoldActive := FALSE; SenseHoldDone := FALSE;
    SenseHoldTimer(IN := FALSE, PT := MaxSenseHoldTime);
    SenseHoldFeedbackTimer(IN := FALSE, PT := DropConfirmDelay);
ELSIF Error OR RestartInhibit THEN
    // Coupure par défaut : le maintien ne survit pas à un défaut (AC9).
    SenseHoldActive := FALSE; SenseHoldDone := FALSE;
    SenseHoldTimer(IN := FALSE); SenseHoldFeedbackTimer(IN := FALSE);
ELSE
    IF MotorRequest THEN
        SenseHoldDone := FALSE;
        SenseHoldActive := FALSE;               // vraie nouvelle demande interrompt le maintien transitoire
    END_IF;
    IF NOT (RequestedRelayFwd OR RequestedRelayRev) THEN
        SenseHoldDone := FALSE;
        SenseHoldActive := FALSE;               // retour au neutre complet : plus rien a tenir
    END_IF;
    IF SenseHoldRequested AND NOT SenseHoldActive AND NOT SenseHoldDone THEN
        SenseHoldActive := TRUE;              // entrée en maintien §3bis
        SenseHoldTimer(IN := FALSE, PT := MaxSenseHoldTime);        // T_max arme au scan suivant
        SenseHoldFeedbackTimer(IN := FALSE, PT := DropConfirmDelay);
    ELSIF SenseHoldActive THEN
        SenseHoldFeedbackTimer(IN := FwdRevSpeedFeedbackOff, PT := DropConfirmDelay);
        SenseHoldTimer(IN := NOT FwdRevSpeedFeedbackOff, PT := MaxSenseHoldTime);
        IF SenseHoldFeedbackTimer.Q THEN
            // Retombée contacteurs CONFIRMÉE -> chute normale du sens (one-shot).
            SenseHoldActive := FALSE; SenseHoldDone := TRUE;
        ELSIF SenseHoldTimer.Q THEN
            // T_max sans confirmation -> chute du sens FORCÉE + latch à acquitter (AC7).
            SenseHoldActive := FALSE;
            ContactorStuckLatched := TRUE;
        END_IF;
    ELSE
        SenseHoldTimer(IN := FALSE); SenseHoldFeedbackTimer(IN := FALSE);
    END_IF;
END_IF;
SenseHoldElapsed := SenseHoldTimer.ET;
ContactorStuck := ContactorStuckLatched;

// ── 4quater. Ordre de relâchement contacteurs (vitesse avant direction) ──
// Quand le mouvement s'arrête (NOT MotorRequest ou SafeStop), les contacteurs
// de VITESSE (Contactor1-4) sont relâchés immédiatement, puis le contacteur de
// DIRECTION (RelayFwd/Rev) après ReleaseOrderDelay (>= 100ms). Protège le moteur :
// on ne coupe jamais la direction pendant que la vitesse est encore engagée.
// Les coupures dures (NOT Enable / PowerContactorEngaged / Error / RestartInhibit)
// restent immédiates (AC9) — l'ordre ne s'applique qu'à l'arrêt commandé.
// Le maintien transitoire §3bis (SenseHold) garde la priorité : quand il est actif,
// c'est lui qui tient la direction (jusqu'à confirmation retombée), pas cet ordre.
IF MotorRequest AND NOT SafeStop THEN
    // Nouvelle demande de mouvement : l'ordre de relâchement est réarmé.
    ReleaseOrderActive := FALSE;
    ReleaseOrderDone := FALSE;
    ReleaseOrderTimer(IN := FALSE, PT := ReleaseOrderDelay);
ELSIF (NOT MotorRequest OR SafeStop) AND NOT ReleaseOrderActive AND NOT ReleaseOrderDone
      AND (RequestedRelayFwd OR RequestedRelayRev) AND NOT SenseHoldActive THEN
    // Arrêt commandé : entrée en ordre de relâchement (vitesse relâchée, direction tenue).
    ReleaseOrderActive := TRUE;
END_IF;

// ── 5. Autorisation moteur ────────────────────────────────────────────────
RelayFwd := FALSE; RelayRev := FALSE;
Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
Busy := FALSE; Done := FALSE; Ready := NOT Error AND NOT ContactorStuckLatched;

IF Error THEN
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.FAULT;
ELSIF RestartInhibit THEN
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    Reason := E_WinchFinalInterlockReason.RESTART_INHIBITED;
    State := E_WinchFinalInterlockState.FAULT;
ELSIF ContactorStuckLatched THEN
    // AC7 : T_max §3bis dépassé sans confirmation retombée -> chute du sens FORCÉE.
    // RelayFwd/Rev et BrakeCmd (= RelayFwd OR RelayRev) retombent à FALSE ci-dessus.
    // Latch à acquittement conscient (ResetEdge) — jamais de redémarrage auto.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    Reason := E_WinchFinalInterlockReason.SENSE_DROP_TIMEOUT;
    State := E_WinchFinalInterlockState.FAULT;
ELSIF ReleaseOrderActive AND NOT PermitFinalBlocked THEN
    // Ordre de relâchement : vitesse relâchée immédiatement, direction tenue
    // jusqu'à ReleaseOrderDelay, puis direction relâchée (AC1/AC2).
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    IF RequestedRelayFwd THEN RelayFwd := TRUE; END_IF;
    IF RequestedRelayRev THEN RelayRev := TRUE; END_IF;
    ReleaseOrderTimer(IN := TRUE, PT := ReleaseOrderDelay);
    ReleaseOrderElapsed := ReleaseOrderTimer.ET;
    IF ReleaseOrderTimer.Q THEN
        ReleaseOrderActive := FALSE;
        ReleaseOrderDone := TRUE;
        RelayFwd := FALSE; RelayRev := FALSE;
    END_IF;
    State := E_WinchFinalInterlockState.READY;
    Busy := TRUE;
ELSIF SafeStop OR PermitFinalBlocked THEN
    // 🛡️ SafeStop ou permis directionnel refusé : coupure dure indépendante de FB_Winch.
    // SafeStop n'est PAS un défaut : pas de FAULT, pas de latch, pas de Reset requis.
    // Les sorties sont coupées tant que l'une des causes est TRUE ; retour nominal dès sa retombée.
    // BrakeCmd (= RelayFwd OR RelayRev, §6) retombe à FALSE automatiquement.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    State := E_WinchFinalInterlockState.READY;
ELSIF SenseHoldActive THEN
    // §3bis : RequestedStep retombé à 0 mais sens encore commandé -> on TIENT le
    // contacteur de sens jusqu'à FwdRevSpeedFeedbackOff (debounced DropConfirmDelay)
    // OU T_max. AuthorizedStep=0 (aucun contacteur de vitesse), seul le sens est tenu.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    IF RequestedRelayFwd THEN RelayFwd := TRUE; END_IF;
    IF RequestedRelayRev THEN RelayRev := TRUE; END_IF;
    State := E_WinchFinalInterlockState.WAIT_SENSE_DROP_CONFIRM;
    Busy := TRUE;
ELSIF NOT MotorRequest THEN
    // Toute annulation de demande annule la temporisation de hausse en cours.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.READY;
ELSIF RestartRequired OR DeadTimePending THEN
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.WAIT_RESTART_DELAY;
    Busy := TRUE;
ELSE
    // ⚡ Progression de palier directe : la temporisation (tempo palier) est gérée
    // par le métier (FB_Winch). La barrière finale transmet directement la consigne
    // sans micro-coupure des contacteurs.
    StepDelay(IN := FALSE, PT := T#1s250ms);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := RequestedStepClamped;

    IF (AuthorizedStep > 0) OR (RequestedStepClamped > 0) THEN
        RelayFwd := RequestedRelayFwd;
        RelayRev := RequestedRelayRev;
        Contactor1 := RequestedContactor1;
        Contactor2 := RequestedContactor2;
        Contactor3 := RequestedContactor3;
        Contactor4 := RequestedContactor4;
    END_IF;

    IF NOT BrakeFeedback THEN
        State := E_WinchFinalInterlockState.WAIT_BRAKE_COMMAND_CONFIRMATION;
        Busy := TRUE;
    ELSE
        State := E_WinchFinalInterlockState.READY;
    END_IF;
END_IF;

// ── 6. Commande frein — couplage direct ────────────────────────────────
// BrakeCmd suit STRUCTURELLEMENT RelayFwd/RelayRev, calculé APRÈS leur
// finalisation ci-dessus (§5) : il hérite donc automatiquement de toutes leurs
// conditions de sécurité (Error, RestartInhibit, RestartRequired, MotorRequest)
// sans avoir à les répéter. Aucun risque d'écart frein/mouvement possible : le
// frein ne PEUT pas être commandé ouvert sans qu'un des deux relais de sens le
// soit aussi, puisque c'est la même expression. PRG_06_Outputs recalcule la
// MÊME expression indépendamment sur les DQ finaux (M1RelayFwd OR M1RelayRev)
// pour piloter physiquement la bobine — ce BrakeCmd ici sert de miroir/diagnostic
// (State, IHM) mais n'est plus câblé sur la sortie physique (voir PRG_06 §2).
BrakeCmd := RelayFwd OR RelayRev;

// ── 6bis. Watchdog frein : uniquement sur la commande RÉELLEMENT FINALE ────
// Watchdog armé sur BrakeCmd (fin §5/§6), JAMAIS sur RequestedRelayFwd/Rev (demande amont pas
// encore autorisée par le state-machine §5 — RestartRequired peut la retenir jusqu'à T#1000ms,
// largement > le seuil 500ms ci-dessous, ce qui déclencherait un faux défaut à chaque redémarrage
// normal).
BrakeTimeout(IN := BrakeCmd AND NOT BrakeFeedback AND NOT RestartInhibit, PT := T#500ms);
BrakeTimeoutElapsed := BrakeTimeout.ET;
IF BrakeTimeout.Q THEN
    BrakeTimeoutCause := TRUE;
ELSIF BrakeFeedback THEN
    BrakeTimeoutCause := FALSE;   // cause réellement disparue (retour desserrage confirmé)
END_IF;
BrakeTimeoutCauseEdge(CLK := BrakeTimeoutCause);
IF BrakeTimeoutCauseEdge.Q THEN
    BrakeTimeoutAck := FALSE;    // nouvelle occurrence -> ré-alarme, ack remis à zéro
    RestartInhibit := TRUE;
    ResetRequired := TRUE;
    NeutralRequestSeen := FALSE;
    RestartRequired := TRUE;
    Reason := E_WinchFinalInterlockReason.BRAKE_COMMAND_NOT_CONFIRMED;
END_IF;
IF ResetEdge.Q THEN
    BrakeTimeoutAck := TRUE;     // toujours effectif, sans condition externe
    ResetRequired := FALSE;
    ContactorStuckLatched := FALSE;   // acquittement conscient du latch T_max §3bis (AC7)
END_IF;
IF BrakeTimeoutCause OR NOT BrakeTimeoutAck THEN
    ErrorId := ErrorId OR 16#0001;
ELSE
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// ── 6bis2. Publication Fault transverse (socle FB_FaultCore) ──────────────
// 🧩 Homogénéisation interface (AF-03 §3) : le défaut est exposé sous la forme
// standard Fault:ST_Fault (comme FB_TranslationOutputInterlock) au lieu du plat
// Error/ErrorId. La cause unique bit0 = timeout frein, strictement identique à la
// gate interne (ErrorId) ; Latching reproduit le latch existant restitué au front
// Reset (jamais de re-armement auto). La gate interne (Error/ErrorId) reste
// inchangée — la publication n'ajoute ni ne modifie aucune coupure.
instCauses[0].Active   := ((ErrorId AND 16#0001) <> 16#0000);
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Timeout confirmation ouverture frein treuil';
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

// ── 6ter. Synchronisation defaut frein en fin de scan (TC-P10-012/013/020) ──
// ErrorId bit0 (defaut frein) est pose en §6bis, APRES la machine d'etat §5.
// Sans ce bloc, la synthese Error et l'etat FAULT accusaient un retard d'un scan
// (~10 ms) sur le watchdog frein. On resynchronise Error/State et on coupe les
// sorties le MEME scan que l'apparition du defaut : c'est un defaut FINAL, coupure
// immediate (jamais un maintien ordonne §3bis).
Error := (ErrorId <> 16#0000);
IF Error THEN
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    BrakeCmd := FALSE;
    AuthorizedStep := 0;
    Busy := FALSE; Done := FALSE; Ready := FALSE;
    State := E_WinchFinalInterlockState.FAULT;
END_IF;

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable THEN
    ContactorMismatch := FALSE;
    MismatchActive := FALSE;
    MismatchTimer(IN := FALSE);
    RETURN;
END_IF;
{endregion}

{region "§2 Detection discordance"}
// 🔍 2. COHÉRENCE DES COMMANDES SÉCURITÉ — verifie que les commandes envoyees
// aux deux treuils sont identiques (sens et contacteurs).
// Concordance ACTIVE des que les 2 treuils sont commandes (relais ou contacteur)
// OU en mode synchronisme (SyncEnable). Seul BypassGlobal neutralise.
// Filtre de 500ms pour tolerer les transitions et rampes.
IF NOT BypassGlobal THEN
    BothCommanded := (RelayFwdM1 OR RelayRevM1 OR Contactor1_M1 OR Contactor2_M1
                      OR Contactor3_M1 OR Contactor4_M1)
                 AND (RelayFwdM2 OR RelayRevM2 OR Contactor1_M2 OR Contactor2_M2
                      OR Contactor3_M2 OR Contactor4_M2);
    MismatchActive := (BothCommanded OR SyncEnable) AND (
        (RelayFwdM1 <> RelayFwdM2) OR
        (RelayRevM1 <> RelayRevM2) OR
        (Contactor1_M1 <> Contactor1_M2) OR
        (Contactor2_M1 <> Contactor2_M2) OR
        (Contactor3_M1 <> Contactor3_M2) OR
        (Contactor4_M1 <> Contactor4_M2)
    );
    MismatchTimer(IN := MismatchActive, PT := T#500ms);
    ContactorMismatch := MismatchTimer.Q;
ELSE
    ContactorMismatch := FALSE;
    MismatchActive := FALSE;
    BothCommanded := FALSE;
    MismatchTimer(IN := FALSE);
END_IF;
{endregion}

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable THEN
    DeltaPosM := 0.0; SignedDeltaPosM := 0.0;
    SyncDeviationWarn := FALSE; SyncDeviationFault := FALSE;
    WarnLatched := FALSE;
    RETURN;
END_IF;
ResetEdge(CLK := Reset);
{endregion}

{region "§2 Calcul ecart"}
// 📏 2. ÉCART M1/M2 — calculé en continu si les 2 treuils sont fiables (HomedAndReliable)
IF HomedAndReliableM1 AND HomedAndReliableM2 THEN
    SignedDeltaPosM := CablePosM1 - CablePosM2 + ActiveOffsetM;
    DeltaPosM := ABS(SignedDeltaPosM);
ELSE
    SignedDeltaPosM := 0.0;
    DeltaPosM := 0.0;
END_IF;
{endregion}

{region "§3 Surveillance ecart 2 seuils"}
// 🔍 3. SURVEILLANCE ECART — 2 seuils (Warn/Fault).
// Warn (seuil 1) = INSTANTANE + LATCH : degrade le palier 1 des que l'ecart depasse,
// sans retard temporel ni oscillation (fidele a l'ancien SyncDegradedStep1).
// Fault (seuil 2) = filtre temporel pour le transitoire mecanique d'arret.
IF NOT BypassGlobal THEN
    WarnActive  := SyncEnable AND HomedAndReliableM1 AND HomedAndReliableM2 AND (DeltaPosM > CfgSyncToleranceM);
    FaultActive := SyncEnable AND HomedAndReliableM1 AND HomedAndReliableM2 AND (DeltaPosM > CfgSyncCriticalToleranceM);

    // Latch Warn : reste actif tant que la cause persiste OU que Reset n'a pas ete demande
    IF WarnActive THEN
        WarnLatched := TRUE;
    ELSIF ResetEdge.Q AND NOT WarnActive THEN
        WarnLatched := FALSE;
    END_IF;
    SyncDeviationWarn := WarnActive OR WarnLatched;

    DeviationFaultTimer(IN := FaultActive, PT := T#800ms);
    SyncDeviationFault := DeviationFaultTimer.Q;
ELSE
    SyncDeviationWarn := FALSE;
    SyncDeviationFault := FALSE;
    WarnLatched := FALSE;
END_IF;
{endregion}
